INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00001000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 1), 'unit1-ex1', 'multiple_choice', 'Choose the correct verb form to complete each sentence.', '[{"id":1,"question":"We ________ to the park every Sunday.","options":["go","went","will go"],"answer":"go","explanation":"Simple Present Affirmative: Subject + V1. \\"Every Sunday\\" indicates a regular habit, so we use Simple Present. \\"Went\\" is past and \\"will go\\" is future — neither fits a habitual action. Simple Present အတည်ပြုပုံ - Subject + V1။ \\"Every Sunday\\" ဆိုတာ ပုံမှန်အလေ့အကျင့်ဖြစ်တဲ့အတွက် Simple Present ကိုသုံးပါ။","points":1},{"id":2,"question":"We ________ to the park because it is raining.","options":["go","don''t go","went"],"answer":"don''t go","explanation":"Simple Present Negative: Subject + don''t + V1. The reason \\"because it is raining\\" gives a present-tense negative context. \\"Go\\" is affirmative and \\"went\\" is past — neither fits the negative present meaning. Simple Present ငြင်းဆိုပုံ - Subject + don''t + V1။","points":1},{"id":3,"question":"________ to the park every Sunday?","options":["Do we go","Did we go","Will we go"],"answer":"Do we go","explanation":"Simple Present Interrogative: Do + subject + V1? Simple Present မေးခွန်းပုံ - Do + subject + V1?","points":1},{"id":4,"question":"________ to the park every Sunday?","options":["Don''t we go","Didn''t we go","Won''t we go"],"answer":"Don''t we go","explanation":"Simple Present Negative Interrogative: Don''t + subject + V1? Simple Present ငြင်းဆိုမေးခွန်း - Don''t + subject + V1?","points":1},{"id":5,"question":"You ________ in the river yesterday.","options":["swam","swim","will swim"],"answer":"swam","explanation":"Simple Past Affirmative: Subject + V2. \\"Yesterday\\" indicates past time. Simple Past အတည်ပြုပုံ - Subject + V2။ \\"Yesterday\\" ဆိုတာ အတိတ်ကာလဖြစ်ပါတယ်။","points":1},{"id":6,"question":"You ________ in the river yesterday.","options":["didn''t swim","don''t swim","won''t swim"],"answer":"didn''t swim","explanation":"Simple Past Negative: Subject + didn''t + V1. Simple Past ငြင်းဆိုပုံ - Subject + didn''t + V1။","points":1},{"id":7,"question":"________ in the river yesterday?","options":["Did you swim","Do you swim","Will you swim"],"answer":"Did you swim","explanation":"Simple Past Interrogative: Did + subject + V1? Simple Past မေးခွန်းပုံ - Did + subject + V1?","points":1},{"id":8,"question":"________ in the river yesterday?","options":["Didn''t you swim","Don''t you swim","Won''t you swim"],"answer":"Didn''t you swim","explanation":"Simple Past Negative Interrogative: Didn''t + subject + V1? Simple Past ငြင်းဆိုမေးခွန်း - Didn''t + subject + V1?","points":1},{"id":9,"question":"It ________ tomorrow morning.","options":["will rain","rained","rains"],"answer":"will rain","explanation":"Simple Future Affirmative: Subject + will + V1. \\"Tomorrow morning\\" indicates future time. Simple Future အတည်ပြုပုံ - Subject + will + V1။ \\"Tomorrow morning\\" ဆိုတာ အနာဂတ်ကာလဖြစ်ပါတယ်။","points":1},{"id":10,"question":"It ________ tomorrow morning.","options":["won''t rain","didn''t rain","doesn''t rain"],"answer":"won''t rain","explanation":"Simple Future Negative: Subject + won''t + V1. Simple Future ငြင်းဆိုပုံ - Subject + won''t + V1။","points":1},{"id":11,"question":"________ tomorrow morning?","options":["Will it rain","Did it rain","Does it rain"],"answer":"Will it rain","explanation":"Simple Future Interrogative: Will + subject + V1? Simple Future မေးခွန်းပုံ - Will + subject + V1?","points":1},{"id":12,"question":"________ tomorrow morning?","options":["Won''t it rain","Didn''t it rain","Doesn''t it rain"],"answer":"Won''t it rain","explanation":"Simple Future Negative Interrogative: Won''t + subject + V1? Simple Future ငြင်းဆိုမေးခွန်း - Won''t + subject + V1?","points":1},{"id":13,"question":"He ________ in Yangon now.","options":["lives","lived","will live"],"answer":"lives","explanation":"Simple Present Affirmative (he/she/it): Subject + V1 + s. \\"Now\\" indicates present time. \\"Lived\\" is past and \\"will live\\" is future — neither fits the present context. Simple Present အတည်ပြုပုံ (he/she/it) - Subject + V1 + s။","points":1},{"id":14,"question":"He ________ in Yangon anymore.","options":["lives","doesn''t live","didn''t live"],"answer":"doesn''t live","explanation":"Simple Present Negative (he/she/it): Subject + doesn''t + V1. \\"Anymore\\" indicates a present negative state. \\"Lives\\" is affirmative and \\"didn''t live\\" is past — neither fits the present negative meaning with \\"anymore\\". Simple Present ငြင်းဆိုပုံ (he/she/it) - Subject + doesn''t + V1။","points":1},{"id":15,"question":"________ he live in Yangon?","options":["Does","Do","Did"],"answer":"Does","explanation":"Simple Present Interrogative (he/she/it): Does + subject + V1? \\"Does\\" is the correct auxiliary for third person singular in present tense. \\"Do\\" is for I/you/we/they and \\"Did\\" is for past. Simple Present မေးခွန်းပုံ (he/she/it) - Does + subject + V1?","points":1},{"id":16,"question":"________ he live in Yangon next year?","options":["Won''t","Doesn''t","Didn''t"],"answer":"Won''t","explanation":"Simple Future Negative Interrogative: Won''t + subject + V1? \\"Next year\\" indicates future time, so we use \\"Won''t\\". \\"Doesn''t\\" is present and \\"Didn''t\\" is past — neither fits the future context. Simple Future ငြင်းဆိုမေးခွန်း - Won''t + subject + V1?","points":1},{"id":17,"question":"She ________ three years ago.","options":["lived","lives","will live"],"answer":"lived","explanation":"Simple Past Affirmative: Subject + V2. \\"Three years ago\\" indicates past time. Simple Past အတည်ပြုပုံ - Subject + V2။ \\"Three years ago\\" ဆိုတာ အတိတ်ကာလဖြစ်ပါတယ်။","points":1},{"id":18,"question":"She ________ three years ago.","options":["didn''t live","doesn''t live","won''t live"],"answer":"didn''t live","explanation":"Simple Past Negative: Subject + didn''t + V1. Simple Past ငြင်းဆိုပုံ - Subject + didn''t + V1။","points":1},{"id":19,"question":"________ three years ago?","options":["Did she live","Does she live","Will she live"],"answer":"Did she live","explanation":"Simple Past Interrogative: Did + subject + V1? Simple Past မေးခွန်းပုံ - Did + subject + V1?","points":1},{"id":20,"question":"________ three years ago?","options":["Didn''t she live","Doesn''t she live","Won''t she live"],"answer":"Didn''t she live","explanation":"Simple Past Negative Interrogative: Didn''t + subject + V1? Simple Past ငြင်းဆိုမေးခွန်း - Didn''t + subject + V1?","points":1},{"id":21,"question":"He ________ next year.","options":["will live","lived","lives"],"answer":"will live","explanation":"Simple Future Affirmative: Subject + will + V1. \\"Next year\\" indicates future time. Simple Future အတည်ပြုပုံ - Subject + will + V1။ \\"Next year\\" ဆိုတာ အနာဂတ်ကာလဖြစ်ပါတယ်။","points":1},{"id":22,"question":"He ________ next year.","options":["won''t live","didn''t live","doesn''t live"],"answer":"won''t live","explanation":"Simple Future Negative: Subject + won''t + V1. Simple Future ငြင်းဆိုပုံ - Subject + won''t + V1။","points":1},{"id":23,"question":"________ next year?","options":["Will he live","Did he live","Does he live"],"answer":"Will he live","explanation":"Simple Future Interrogative: Will + subject + V1? Simple Future မေးခွန်းပုံ - Will + subject + V1?","points":1},{"id":24,"question":"________ next year?","options":["Won''t he live","Didn''t he live","Doesn''t he live"],"answer":"Won''t he live","explanation":"Simple Future Negative Interrogative: Won''t + subject + V1? Simple Future ငြင်းဆိုမေးခွန်း - Won''t + subject + V1?","points":1},{"id":25,"question":"Do we go to the park every Sunday? Yes, ________.","options":["we do","we did","we will"],"answer":"we do","explanation":"The question uses ''Do'' (Simple Present) with ''every Sunday'', so the short answer must also be Simple Present: ''we do''. မေးခွန်းက ''Do'' (Simple Present) နဲ့ ''every Sunday'' သုံးထားတဲ့အတွက် အဖြေကလည်း Simple Present ''we do'' ဖြစ်ရပါမယ်။","points":1},{"id":26,"question":"Do we go to the park every Sunday? No, ________.","options":["we don''t","we didn''t","we won''t"],"answer":"we don''t","explanation":"The question uses ''Do'' (Simple Present) with ''every Sunday'', so the short negative answer must be ''we don''t''. မေးခွန်းက ''Do'' (Simple Present) နဲ့ ''every Sunday'' သုံးထားတဲ့အတွက် အဖြေက ''we don''t'' ဖြစ်ရပါမယ်။","points":1},{"id":27,"question":"Did we go to the park yesterday? Yes, ________.","options":["we did","we do","we will"],"answer":"we did","explanation":"The question uses ''Did'' (Simple Past) with ''yesterday'', so the short answer must be ''we did''. မေးခွန်းက ''Did'' (Simple Past) နဲ့ ''yesterday'' သုံးထားတဲ့အတွက် အဖြေက ''we did'' ဖြစ်ရပါမယ်။","points":1},{"id":28,"question":"Did we go to the park yesterday? No, ________.","options":["we didn''t","we don''t","we won''t"],"answer":"we didn''t","explanation":"The question uses ''Did'' (Simple Past) with ''yesterday'', so the short negative answer must be ''we didn''t''. မေးခွန်းက ''Did'' (Simple Past) နဲ့ ''yesterday'' သုံးထားတဲ့အတွက် အဖြေက ''we didn''t'' ဖြစ်ရပါမယ်။","points":1},{"id":29,"question":"Will we go to the park tomorrow? Yes, ________.","options":["we will","we do","we did"],"answer":"we will","explanation":"The question uses ''Will'' (Simple Future) with ''tomorrow'', so the short answer must be ''we will''. မေးခွန်းက ''Will'' (Simple Future) နဲ့ ''tomorrow'' သုံးထားတဲ့အတွက် အဖြေက ''we will'' ဖြစ်ရပါမယ်။","points":1},{"id":30,"question":"Will we go to the park tomorrow? No, ________.","options":["we won''t","we don''t","we didn''t"],"answer":"we won''t","explanation":"The question uses ''Will'' (Simple Future) with ''tomorrow'', so the short negative answer must be ''we won''t''. မေးခွန်းက ''Will'' (Simple Future) နဲ့ ''tomorrow'' သုံးထားတဲ့အတွက် အဖြေက ''we won''t'' ဖြစ်ရပါမယ်။","points":1},{"id":31,"question":"Does he live in Yangon? Yes, ________.","options":["he does","he do","he will"],"answer":"he does","explanation":"The question uses ''Does'' (Simple Present, he/she/it), so the short answer must be ''he does''. မေးခွန်းက ''Does'' (Simple Present, he/she/it) သုံးထားတဲ့အတွက် အဖြေက ''he does'' ဖြစ်ရပါမယ်။","points":1},{"id":32,"question":"Does he live in Yangon? No, ________.","options":["he doesn''t","he don''t","he won''t"],"answer":"he doesn''t","explanation":"The question uses ''Does'' (Simple Present, he/she/it), so the short negative answer must be ''he doesn''t''. မေးခွန်းက ''Does'' (Simple Present, he/she/it) သုံးထားတဲ့အတွက် အဖြေက ''he doesn''t'' ဖြစ်ရပါမယ်။","points":1},{"id":33,"question":"Did he live in Yangon three years ago? Yes, ________.","options":["he did","he does","he will"],"answer":"he did","explanation":"The question uses ''Did'' (Simple Past) with ''three years ago'', so the short answer must be ''he did''. မေးခွန်းက ''Did'' (Simple Past) နဲ့ ''three years ago'' သုံးထားတဲ့အတွက် အဖြေက ''he did'' ဖြစ်ရပါမယ်။","points":1},{"id":34,"question":"Did he live in Yangon three years ago? No, ________.","options":["he didn''t","he doesn''t","he won''t"],"answer":"he didn''t","explanation":"The question uses ''Did'' (Simple Past) with ''three years ago'', so the short negative answer must be ''he didn''t''. မေးခွန်းက ''Did'' (Simple Past) နဲ့ ''three years ago'' သုံးထားတဲ့အတွက် အဖြေက ''he didn''t'' ဖြစ်ရပါမယ်။","points":1},{"id":35,"question":"Will he live in Yangon next year? Yes, ________.","options":["he will","he does","he did"],"answer":"he will","explanation":"The question uses ''Will'' (Simple Future) with ''next year'', so the short answer must be ''he will''. မေးခွန်းက ''Will'' (Simple Future) နဲ့ ''next year'' သုံးထားတဲ့အတွက် အဖြေက ''he will'' ဖြစ်ရပါမယ်။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00001001-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 1), 'unit1-ex2', 'multiple_choice', 'Choose the correct verb form.', '[{"id":36,"question":"They ________ to Bagan last month.","options":["went","go","will go"],"answer":"went","explanation":"Simple Past tense of ''go'' is ''went''. ''Last month'' indicates past time. go ရဲ့ V2 က went ဖြစ်ပါတယ်။ ''Last month'' ဆိုတာ အတိတ်ကာလဖြစ်ပါတယ်။","points":1},{"id":37,"question":"You ________ at Mandalay next month.","options":["will stay","stayed","stay"],"answer":"will stay","explanation":"''Next month'' indicates future time, so we use ''will + V1''. ''Next month'' ဆိုတာ အနာဂတ်ကာလဖြစ်တဲ့အတွက် will + V1 ကိုသုံးပါ။","points":1},{"id":38,"question":"She doesn''t ________ loudly.","options":["talk","talks","talked"],"answer":"talk","explanation":"After ''doesn''t'', we use the base form (V1). doesn''t ပြီးနောက်မှာ V1 ကိုသုံးပါ။","points":1},{"id":39,"question":"Her brother ________ all the time.","options":["works","worked","worker"],"answer":"works","explanation":"Simple Present with ''he'' (her brother) uses ''V1 + s''. ''All the time'' indicates a habitual action in present. he နဲ့ Simple Present မှာ V1 + s ကိုသုံးပါ။ ''All the time'' ဆိုတာ ပုံမှန်အလေ့အကျင့်ကိုဖော်ပြပါတယ်။","points":1},{"id":40,"question":"Do you think he will ________ you?","options":["remember","remembered","remembering"],"answer":"remember","explanation":"After ''will'', we use the base form (V1). will ပြီးနောက်မှာ V1 ကိုသုံးပါ။","points":1},{"id":41,"question":"I always ________ in the winter.","options":["ski","skies","skiing"],"answer":"ski","explanation":"Simple Present with ''I'' uses the base form (V1). ''Always'' indicates a habitual action. I နဲ့ Simple Present မှာ V1 ကိုသုံးပါ။ ''Always'' ဆိုတာ ပုံမှန်အလေ့အကျင့်ကိုဖော်ပြပါတယ်။","points":1},{"id":42,"question":"She won''t ________ him.","options":["love","loves","loved"],"answer":"love","explanation":"After ''won''t'', we use the base form (V1). won''t ပြီးနောက်မှာ V1 ကိုသုံးပါ။","points":1},{"id":43,"question":"________ she cry yesterday?","options":["Did","Do","Does"],"answer":"Did","explanation":"''Yesterday'' indicates past time, so we use ''Did''. မနေ့ကဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် Did ကိုသုံးပါ။","points":1},{"id":44,"question":"You can ________ it.","options":["do","does","did"],"answer":"do","explanation":"After modal verbs like ''can'', we use the base form (V1). can လို modal verb ပြီးနောက်မှာ V1 ကိုသုံးပါ။","points":1},{"id":45,"question":"Don''t you ________ your guitar?","options":["forget","forgot","forgotten"],"answer":"forget","explanation":"After ''Don''t'', we use the base form (V1). Don''t ပြီးနောက်မှာ V1 ကိုသုံးပါ။","points":1},{"id":46,"question":"________ you like fizzy drinks every day?","options":["Do","Does","Did"],"answer":"Do","explanation":"Simple Present with ''you'' uses ''Do''. ''Every day'' indicates present habitual time. ''Does'' is for he/she/it and ''Did'' is for past — neither fits. you နဲ့ Simple Present မှာ Do ကိုသုံးပါ။ ''Every day'' ဆိုတာ ပုံမှန်အလေ့အကျင့်ကိုဖော်ပြပါတယ်။","points":1},{"id":47,"question":"________ in a small group and discuss your answers.","options":["Work","Working","Worked"],"answer":"Work","explanation":"Imperative form uses the base form (V1). အမိန့်ပေးသည့်ပုံစံမှာ V1 ကိုသုံးပါ။","points":1},{"id":48,"question":"She ________ Greek Yoghurt every day.","options":["loves","love","loved"],"answer":"loves","explanation":"Simple Present with ''she'' uses ''V1 + s''. ''Every day'' indicates present habitual time. ''Love'' doesn''t agree with ''she'' and ''loved'' is past — neither fits. she နဲ့ Simple Present မှာ V1 + s ကိုသုံးပါ။ ''Every day'' ဆိုတာ ပုံမှန်အလေ့အကျင့်ကိုဖော်ပြပါတယ်။","points":1},{"id":49,"question":"The fans ________ the star outside the cinema last night.","options":["met","meets","meeting"],"answer":"met","explanation":"Simple Past tense of ''meet'' is ''met''. ''Last night'' indicates past time. meet ရဲ့ V2 က met ဖြစ်ပါတယ်။ ''Last night'' ဆိုတာ အတိတ်ကာလဖြစ်ပါတယ်။","points":1},{"id":50,"question":"I ________ washing dishes every day.","options":["hate","hates","hated"],"answer":"hate","explanation":"Simple Present with ''I'' uses the base form (V1). ''Every day'' indicates present habitual time. ''Hates'' doesn''t agree with ''I'' and ''hated'' is past — neither fits. I နဲ့ Simple Present မှာ V1 ကိုသုံးပါ။ ''Every day'' ဆိုတာ ပုံမှန်အလေ့အကျင့်ကိုဖော်ပြပါတယ်။","points":1},{"id":51,"question":"Yesterday afternoon my sister ________ a chocolate cake.","options":["made","make","makes"],"answer":"made","explanation":"Simple Past tense of ''make'' is ''made''. ''Yesterday afternoon'' indicates past time. make ရဲ့ V2 က made ဖြစ်ပါတယ်။ ''Yesterday afternoon'' ဆိုတာ အတိတ်ကာလဖြစ်ပါတယ်။","points":1},{"id":52,"question":"Susan ________ a new dress to the party last weekend.","options":["wore","wears","worn"],"answer":"wore","explanation":"Simple Past tense of ''wear'' is ''wore''. ''Last weekend'' indicates past time. wear ရဲ့ V2 က wore ဖြစ်ပါတယ်။ ''Last weekend'' ဆိုတာ အတိတ်ကာလဖြစ်ပါတယ်။","points":1},{"id":53,"question":"James and Alice ________ football next Sunday.","options":["will play","plays","play"],"answer":"will play","explanation":"''Next Sunday'' indicates future time, so we use ''will + V1''. ''Next Sunday'' ဆိုတာ အနာဂတ်ကာလဖြစ်တဲ့အတွက် will + V1 ကိုသုံးပါ။","points":1},{"id":54,"question":"Polar bears ________ soon.","options":["will disappear","disappear","disappeared"],"answer":"will disappear","explanation":"''Soon'' indicates future time, so we use ''will + V1''. ''Soon'' ဆိုတာ အနာဂတ်ကာလဖြစ်တဲ့အတွက် will + V1 ကိုသုံးပါ။","points":1},{"id":55,"question":"________ you see the new TV series last night?","options":["Did","Do","Does"],"answer":"Did","explanation":"''Last night'' indicates past time, so we use ''Did''. မနေ့ညကဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် Did ကိုသုံးပါ။","points":1},{"id":56,"question":"I am taking an umbrella because the weather forecast said that it ________ later.","options":["will rain","rains","rained"],"answer":"will rain","explanation":"''Later'' indicates future time, so we use ''will + V1''. ''Later'' ဆိုတာ အနာဂတ်ကာလဖြစ်တဲ့အတွက် will + V1 ကိုသုံးပါ။","points":1},{"id":57,"question":"I ________ an eagle while I was walking in the mountains.","options":["saw","see","seeing"],"answer":"saw","explanation":"Simple Past tense of ''see'' is ''saw''. ''While I was walking'' indicates past time. see ရဲ့ V2 က saw ဖြစ်ပါတယ်။ ''While I was walking'' ဆိုတာ အတိတ်ကာလကိုဖော်ပြပါတယ်။","points":1},{"id":58,"question":"It ________ your vocabularies every day.","options":["increases","increase","increased"],"answer":"increases","explanation":"Simple Present with ''it'' uses ''V1 + s''. ''Every day'' indicates present habitual time. ''Increase'' doesn''t agree with ''it'' and ''increased'' is past — neither fits. it နဲ့ Simple Present မှာ V1 + s ကိုသုံးပါ။ ''Every day'' ဆိုတာ ပုံမှန်အလေ့အကျင့်ကိုဖော်ပြပါတယ်။","points":1},{"id":59,"question":"I ________ coffee when I was 11.","options":["liked","like","likes"],"answer":"liked","explanation":"Simple Past tense because ''when I was 11'' indicates past time. ''When I was 11'' ဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် V2 ကိုသုံးပါ။","points":1},{"id":60,"question":"I didn''t ________ sport last weekend.","options":["do","does","doing"],"answer":"do","explanation":"After ''didn''t'', we use the base form (V1). didn''t ပြီးနောက်မှာ V1 ကိုသုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00001002-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 1), 'unit1-ex3', 'multiple_choice', 'Choose the correct English translation.', '[{"id":61,"question":"ကျွန်မ မင်းကို ယုံတယ်။ (I / you / believe in)","options":["I believe in you.","I didn''t believe in you.","Will I believe in you?"],"answer":"I believe in you.","explanation":"Simple Present Affirmative: Subject + V1 + object. ''တယ်'' indicates present affirmative. Simple Present အတည်ပြုပုံ - Subject + V1 + object။","points":2},{"id":62,"question":"မင်း ငါ့ကို ကူညီမလား။ (you / me / help)","options":["Will you help me?","Do you help me?","Didn''t you help me?"],"answer":"Will you help me?","explanation":"Simple Future Interrogative: Will + subject + V1? ''မလား'' indicates future question. Simple Future မေးခွန်းပုံ - Will + subject + V1?","points":2},{"id":63,"question":"သူမ မနက်ဖန် ကျောင်းသို့ သွားမှာမယ်။ (She / tomorrow / go to school)","options":["She will go to school tomorrow.","She goes to school tomorrow.","She didn''t go to school tomorrow."],"answer":"She will go to school tomorrow.","explanation":"Simple Future Affirmative: Subject + will + V1. ''Tomorrow'' and ''မှာမယ်'' indicate future. Simple Future အတည်ပြုပုံ - Subject + will + V1။","points":2},{"id":64,"question":"သူ ငါ့ကို မမှတ်မိခဲ့ပါ။ (He / me / forgot)","options":["He didn''t forget me.","He doesn''t forget me.","Won''t he forget me?"],"answer":"He didn''t forget me.","explanation":"Simple Past Negative: Subject + didn''t + V1. ''ခဲ့ပါ။'' indicates past negative. Simple Past ငြင်းဆိုပုံ - Subject + didn''t + V1။","points":2},{"id":65,"question":"မင်းတို့ ပန်းကန် မဆေးဘူးလား။ (you / wash the dishes)","options":["Don''t you wash the dishes?","Do you wash the dishes?","Didn''t you wash the dishes?"],"answer":"Don''t you wash the dishes?","explanation":"Simple Present Negative Interrogative: Don''t + subject + V1? ''ဘူးလား'' indicates a negative question in present. Simple Present ငြင်းဆိုမေးခွန်း - Don''t + subject + V1?","points":2},{"id":66,"question":"မနေ့က သူမ အဝတ်တွေ မညှစ်တက်ခဲ့လား။ (she / yesterday / iron the clothes)","options":["Did she iron the clothes yesterday?","Does she iron the clothes yesterday?","Will she iron the clothes yesterday?"],"answer":"Did she iron the clothes yesterday?","explanation":"Simple Past Interrogative: Did + subject + V1? ''မနေ့က'' indicates past. Simple Past မေးခွန်းပုံ - Did + subject + V1?","points":2},{"id":67,"question":"သူမ မင်းရဲ့ပန်းသီး ကို စားမှာ မဟုတ်ဘူး။ (She / eat / your apples)","options":["She won''t eat your apples.","She doesn''t eat your apples.","She didn''t eat your apples."],"answer":"She won''t eat your apples.","explanation":"Simple Future Negative: Subject + won''t + V1. ''မှာ မဟုတ်ဘူး'' indicates future negative. Simple Future ငြင်းဆိုပုံ - Subject + won''t + V1။","points":2},{"id":68,"question":"သူ ဂျာမနီမှာ မနေဘူး မဟုတ်လား။ (he / in Germany / live)","options":["Doesn''t he live in Germany?","Didn''t he live in Germany?","Won''t he live in Germany?"],"answer":"Doesn''t he live in Germany?","explanation":"Simple Present Negative Interrogative: Doesn''t + subject + V1? ''ဘူးလား'' indicates a negative question in present. Simple Present ငြင်းဆိုမေးခွန်း - Doesn''t + subject + V1?","points":2},{"id":69,"question":"သူမက အင်္ဂလိပ်သဒ္ဒါကို တခြားသူတွေနဲ့ မျှဝတယ်။ (She / English grammar / share / to other)","options":["She shares English grammar with others.","She shared English grammar with others.","She will share English grammar with others."],"answer":"She shares English grammar with others.","explanation":"Simple Present Affirmative: Subject + V1 + s. ''တယ်'' indicates present affirmative. Simple Present အတည်ပြုပုံ - Subject + V1 + s။","points":2},{"id":70,"question":"သူတို့ ဒီနေ့ အတန်းမတက်ခဲ့ဘူး။ (They / today / attend the class)","options":["They didn''t attend the class today.","They don''t attend the class today.","They won''t attend the class today."],"answer":"They didn''t attend the class today.","explanation":"Simple Past Negative: Subject + didn''t + V1. ''ခဲ့ဘူး'' indicates past negative. Simple Past ငြင်းဆိုပုံ - Subject + didn''t + V1။","points":2},{"id":71,"question":"ငါတို့ မင်းကို နားလည်မှားခဲ့ကတယ်။ (We / you / misunderstood)","options":["We misunderstood you.","We misunderstand you.","We will misunderstand you."],"answer":"We misunderstood you.","explanation":"Simple Past Affirmative: Subject + V2. ''ခဲ့ကတယ်'' indicates past. Simple Past အတည်ပြုပုံ - Subject + V2။","points":2},{"id":72,"question":"မင်း အစောရုံ စောစော မထဘူးလား။ (you / get up early)","options":["Don''t you get up early?","Do you get up early?","Didn''t you get up early?"],"answer":"Don''t you get up early?","explanation":"Simple Present Negative Interrogative: Don''t + subject + V1? ''ဘူးလား'' indicates a negative question in present. Simple Present ငြင်းဆိုမေးခွန်း - Don''t + subject + V1?","points":2},{"id":73,"question":"မကြာခင် သူ ဘူတာကို ရောက်လာမှာမယ်။ (soon / he / arrive at the station)","options":["He will arrive at the station soon.","He arrives at the station soon.","He didn''t arrive at the station soon."],"answer":"He will arrive at the station soon.","explanation":"Simple Future Affirmative: Subject + will + V1. ''မကြာခင်'' and ''မှာမယ်'' indicate future. Simple Future အတည်ပြုပုံ - Subject + will + V1။","points":2},{"id":74,"question":"သူမ သူ့ကို မချစ်ချပါဘူး။ (She / him / love)","options":["She doesn''t love him.","She didn''t love him.","She won''t love him."],"answer":"She doesn''t love him.","explanation":"Simple Present Negative: Subject + doesn''t + V1. ''ပါဘူး'' indicates present negative. Simple Present ငြင်းဆိုပုံ - Subject + doesn''t + V1။","points":2},{"id":75,"question":"သူတို့ မနက်ဖန် ဘောလုံးကန်ကြမှာမယ်။ (They / tomorrow / play the football)","options":["They will play football tomorrow.","They play football tomorrow.","They didn''t play football tomorrow."],"answer":"They will play football tomorrow.","explanation":"Simple Future Affirmative: Subject + will + V1. ''မနက်ဖန်'' and ''မှာမယ်'' indicate future. Simple Future အတည်ပြုပုံ - Subject + will + V1။","points":2}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

-- --------------------------------------------------------------------------
-- Unit 2 Exercises
-- --------------------------------------------------------------------------

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00002000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 2), 'unit2-ex1', 'multiple_choice', 'Choose the correct form of ''to be'' to complete each sentence.', '[{"id":201,"question":"I ________ a student.","options":["am","is","are"],"answer":"am","explanation":"With ''I'', we use ''am''. ''I am'' is the correct form of ''be'' for first person singular. ''I'' နဲ့ ''am'' ကိုသုံးပါ။","points":1},{"id":202,"question":"She ________ happy today.","options":["am","is","are"],"answer":"is","explanation":"With ''she'', we use ''is''. ''She is'' is the correct form of ''be'' for third person singular. ''She'' နဲ့ ''is'' ကိုသုံးပါ။","points":1},{"id":203,"question":"They ________ in the park now.","options":["am","is","are"],"answer":"are","explanation":"With ''they'', we use ''are''. ''They are'' is the correct form of ''be'' for third person plural. ''They'' နဲ့ ''are'' ကိုသုံးပါ။","points":1},{"id":204,"question":"We ________ at school every day.","options":["am","is","are"],"answer":"are","explanation":"With ''we'', we use ''are''. ''We are'' is the correct form of ''be'' for first person plural. ''We'' နဲ့ ''are'' ကိုသုံးပါ။","points":1},{"id":205,"question":"He ________ a doctor.","options":["am","is","are"],"answer":"is","explanation":"With ''he'', we use ''is''. ''He is'' is the correct form of ''be'' for third person singular. ''He'' နဲ့ ''is'' ကိုသုံးပါ။","points":1},{"id":206,"question":"You ________ my friend.","options":["am","is","are"],"answer":"are","explanation":"With ''you'', we use ''are''. ''You are'' is the correct form of ''be'' for second person. ''You'' နဲ့ ''are'' ကိုသုံးပါ။","points":1},{"id":207,"question":"It ________ rainy today.","options":["am","is","are"],"answer":"is","explanation":"With ''it'', we use ''is''. ''It is'' is the correct form of ''be'' for third person singular. ''It'' နဲ့ ''is'' ကိုသုံးပါ။","points":1},{"id":208,"question":"I ________ at home last night.","options":["was","were","am"],"answer":"was","explanation":"With ''I'' in the past tense, we use ''was''. ''Last night'' indicates past time. ''I'' နဲ့ အတိတ်ကာလမှာ ''was'' ကိုသုံးပါ။","points":1},{"id":209,"question":"She ________ tired yesterday.","options":["was","were","is"],"answer":"was","explanation":"With ''she'' in the past tense, we use ''was''. ''Yesterday'' indicates past time. ''She'' နဲ့ အတိတ်ကာလမှာ ''was'' ကိုသုံးပါ။","points":1},{"id":210,"question":"They ________ at the market last week.","options":["was","were","are"],"answer":"were","explanation":"With ''they'' in the past tense, we use ''were''. ''Last week'' indicates past time. ''They'' နဲ့ အတိတ်ကာလမှာ ''were'' ကိုသုံးပါ။","points":1},{"id":211,"question":"We ________ at school yesterday.","options":["was","were","are"],"answer":"were","explanation":"With ''we'' in the past tense, we use ''were''. ''Yesterday'' indicates past time. ''We'' နဲ့ အတိတ်ကာလမှာ ''were'' ကိုသုံးပါ။","points":1},{"id":212,"question":"He ________ a student two years ago.","options":["was","were","is"],"answer":"was","explanation":"With ''he'' in the past tense, we use ''was''. ''Two years ago'' indicates past time. ''He'' နဲ့ အတိတ်ကာလမှာ ''was'' ကိုသုံးပါ။","points":1},{"id":213,"question":"You ________ happy yesterday.","options":["was","were","are"],"answer":"were","explanation":"With ''you'' in the past tense, we use ''were''. ''Yesterday'' indicates past time. ''You'' နဲ့ အတိတ်ကာလမှာ ''were'' ကိုသုံးပါ။","points":1},{"id":214,"question":"It ________ cold yesterday.","options":["was","were","is"],"answer":"was","explanation":"With ''it'' in the past tense, we use ''was''. ''Yesterday'' indicates past time. ''It'' နဲ့ အတိတ်ကာလမှာ ''was'' ကိုသုံးပါ။","points":1},{"id":215,"question":"I ________ a doctor next year.","options":["will be","am","was"],"answer":"will be","explanation":"For future tense with ''I'', we use ''will be''. ''Next year'' indicates future time. ''I'' နဲ့ အနာဂတ်ကာလမှာ ''will be'' ကိုသုံးပါ။","points":1},{"id":216,"question":"She ________ happy tomorrow.","options":["will be","is","was"],"answer":"will be","explanation":"For future tense with ''she'', we use ''will be''. ''Tomorrow'' indicates future time. ''She'' နဲ့ အနာဂတ်ကာလမှာ ''will be'' ကိုသုံးပါ။","points":1},{"id":217,"question":"They ________ at school next Monday.","options":["will be","are","were"],"answer":"will be","explanation":"For future tense with ''they'', we use ''will be''. ''Next Monday'' indicates future time. ''They'' နဲ့ အနာဂတ်ကာလမှာ ''will be'' ကိုသုံးပါ။","points":1},{"id":218,"question":"We ________ at home tomorrow.","options":["will be","are","were"],"answer":"will be","explanation":"For future tense with ''we'', we use ''will be''. ''Tomorrow'' indicates future time. ''We'' နဲ့ အနာဂတ်ကာလမှာ ''will be'' ကိုသုံးပါ။","points":1},{"id":219,"question":"He ________ here soon.","options":["will be","is","was"],"answer":"will be","explanation":"For future tense with ''he'', we use ''will be''. ''Soon'' indicates future time. ''He'' နဲ့ အနာဂတ်ကာလမှာ ''will be'' ကိုသုံးပါ။","points":1},{"id":220,"question":"You ________ late next time.","options":["will be","are","were"],"answer":"will be","explanation":"For future tense with ''you'', we use ''will be''. ''Next time'' indicates future time. ''You'' နဲ့ အနာဂတ်ကာလမှာ ''will be'' ကိုသုံးပါ။","points":1},{"id":221,"question":"It ________ hot next week.","options":["will be","is","was"],"answer":"will be","explanation":"For future tense with ''it'', we use ''will be''. ''Next week'' indicates future time. ''It'' နဲ့ အနာဂတ်ကာလမှာ ''will be'' ကိုသုံးပါ။","points":1},{"id":222,"question":"I ________ not a doctor.","options":["am","is","are"],"answer":"am","explanation":"Negative form with ''I'' is ''am not''. ''I am not'' is the correct negative form. ''I'' နဲ့ ငြင်းဆိုပုံ ''am not'' ဖြစ်ပါတယ်။","points":1},{"id":223,"question":"She ________ not beautiful.","options":["am","is","are"],"answer":"is","explanation":"Negative form with ''she'' is ''is not''. ''She is not'' is the correct negative form. ''She'' နဲ့ ငြင်းဆိုပုံ ''is not'' ဖြစ်ပါတယ်။","points":1},{"id":224,"question":"They ________ not at home.","options":["am","is","are"],"answer":"are","explanation":"Negative form with ''they'' is ''are not''. ''They are not'' is the correct negative form. ''They'' နဲ့ ငြင်းဆိုပုံ ''are not'' ဖြစ်ပါတယ်။","points":1},{"id":225,"question":"________ you a student?","options":["Are","Is","Am"],"answer":"Are","explanation":"Interrogative form with ''you'' starts with ''Are''. ''Are you a student?'' is the correct question form. ''You'' နဲ့ မေးခွန်းပုံ ''Are you...?'' ဖြစ်ပါတယ်။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00002001-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 2), 'unit2-ex2', 'multiple_choice', 'Choose the correct answer to complete the short answer.', '[{"id":226,"question":"Is he a doctor? Yes, ________.","options":["he is","he are","he am"],"answer":"he is","explanation":"Short answer uses the same form of ''be'' as the question. The question uses ''Is he'', so the answer is ''he is''. မေးခွန်းက ''Is he'' ဖြစ်တဲ့အတွက် အဖြေက ''he is'' ဖြစ်ရပါမယ်။","points":1},{"id":227,"question":"Is he a doctor? No, ________.","options":["he isn''t","he aren''t","he amn''t"],"answer":"he isn''t","explanation":"Negative short answer uses the negative form of ''be''. The question uses ''Is he'', so the negative answer is ''he isn''t''. မေးခွန်းက ''Is he'' ဖြစ်တဲ့အတွက် အဖြေက ''he isn''t'' ဖြစ်ရပါမယ်။","points":1},{"id":228,"question":"Are they at home? Yes, ________.","options":["they are","they is","they am"],"answer":"they are","explanation":"Short answer uses the same form of ''be'' as the question. The question uses ''Are they'', so the answer is ''they are''. မေးခွန်းက ''Are they'' ဖြစ်တဲ့အတွက် အဖြေက ''they are'' ဖြစ်ရပါမယ်။","points":1},{"id":229,"question":"Are they at home? No, ________.","options":["they aren''t","they isn''t","they amn''t"],"answer":"they aren''t","explanation":"Negative short answer uses the negative form of ''be''. The question uses ''Are they'', so the negative answer is ''they aren''t''. မေးခွန်းက ''Are they'' ဖြစ်တဲ့အတွက် အဖြေက ''they aren''t'' ဖြစ်ရပါမယ်။","points":1},{"id":230,"question":"Was she happy yesterday? Yes, ________.","options":["she was","she were","she is"],"answer":"she was","explanation":"Short answer uses the same form of ''be'' as the question. The question uses ''Was she'', so the answer is ''she was''. မေးခွန်းက ''Was she'' ဖြစ်တဲ့အတွက် အဖြေက ''she was'' ဖြစ်ရပါမယ်။","points":1},{"id":231,"question":"Was she happy yesterday? No, ________.","options":["she wasn''t","she weren''t","she isn''t"],"answer":"she wasn''t","explanation":"Negative short answer uses the negative form of ''be''. The question uses ''Was she'', so the negative answer is ''she wasn''t''. မေးခွန်းက ''Was she'' ဖြစ်တဲ့အတွက် အဖြေက ''she wasn''t'' ဖြစ်ရပါမယ်။","points":1},{"id":232,"question":"Were they at school yesterday? Yes, ________.","options":["they were","they was","they are"],"answer":"they were","explanation":"Short answer uses the same form of ''be'' as the question. The question uses ''Were they'', so the answer is ''they were''. မေးခွန်းက ''Were they'' ဖြစ်တဲ့အတွက် အဖြေက ''they were'' ဖြစ်ရပါမယ်။","points":1},{"id":233,"question":"Were they at school yesterday? No, ________.","options":["they weren''t","they wasn''t","they aren''t"],"answer":"they weren''t","explanation":"Negative short answer uses the negative form of ''be''. The question uses ''Were they'', so the negative answer is ''they weren''t''. မေးခွန်းက ''Were they'' ဖြစ်တဲ့အတွက် အဖြေက ''they weren''t'' ဖြစ်ရပါမယ်။","points":1},{"id":234,"question":"Will he be here soon? Yes, ________.","options":["he will","he is","he was"],"answer":"he will","explanation":"Short answer uses the same auxiliary verb as the question. The question uses ''Will he'', so the answer is ''he will''. မေးခွန်းက ''Will he'' ဖြစ်တဲ့အတွက် အဖြေက ''he will'' ဖြစ်ရပါမယ်။","points":1},{"id":235,"question":"Will he be here soon? No, ________.","options":["he won''t","he isn''t","he wasn''t"],"answer":"he won''t","explanation":"Negative short answer uses the negative form of the auxiliary verb. The question uses ''Will he'', so the negative answer is ''he won''t''. မေးခွန်းက ''Will he'' ဖြစ်တဲ့အတွက် အဖြေက ''he won''t'' ဖြစ်ရပါမယ်။","points":1},{"id":236,"question":"Will they be at school next Monday? Yes, ________.","options":["they will","they are","they were"],"answer":"they will","explanation":"Short answer uses the same auxiliary verb as the question. The question uses ''Will they'', so the answer is ''they will''. မေးခွန်းက ''Will they'' ဖြစ်တဲ့အတွက် အဖြေက ''they will'' ဖြစ်ရပါမယ်။","points":1},{"id":237,"question":"Will they be at school next Monday? No, ________.","options":["they won''t","they aren''t","they weren''t"],"answer":"they won''t","explanation":"Negative short answer uses the negative form of the auxiliary verb. The question uses ''Will they'', so the negative answer is ''they won''t''. မေးခွန်းက ''Will they'' ဖြစ်တဲ့အတွက် အဖြေက ''they won''t'' ဖြစ်ရပါမယ်။","points":1},{"id":238,"question":"Am I a student? Yes, ________.","options":["you are","you is","you am"],"answer":"you are","explanation":"When answering a question about ''I'', we change ''I'' to ''you'' in the answer. The question uses ''Am I'', so the answer is ''you are''. ''I'' အကြောင်း မေးတဲ့အခါ အဖြေမှာ ''you'' ကိုသုံးပါ။","points":1},{"id":239,"question":"Am I a student? No, ________.","options":["you aren''t","you isn''t","you amn''t"],"answer":"you aren''t","explanation":"When answering a question about ''I'', we change ''I'' to ''you'' in the answer. The question uses ''Am I'', so the negative answer is ''you aren''t''. ''I'' အကြောင်း မေးတဲ့အခါ အဖြေမှာ ''you'' ကိုသုံးပါ။","points":1},{"id":240,"question":"Are you my friend? Yes, ________.","options":["I am","I is","I are"],"answer":"I am","explanation":"When answering a question about ''you'', we change ''you'' to ''I'' in the answer. The question uses ''Are you'', so the answer is ''I am''. ''you'' အကြောင်း မေးတဲ့အခါ အဖြေမှာ ''I'' ကိုသုံးပါ။","points":1},{"id":241,"question":"Are you my friend? No, ________.","options":["I''m not","I isn''t","I aren''t"],"answer":"I''m not","explanation":"When answering a question about ''you'', we change ''you'' to ''I'' in the answer. The question uses ''Are you'', so the negative answer is ''I''m not''. ''you'' အကြောင်း မေးတဲ့အခါ အဖြေမှာ ''I'' ကိုသုံးပါ။","points":1},{"id":242,"question":"Was he at home last night? Yes, ________.","options":["he was","he were","he is"],"answer":"he was","explanation":"Short answer uses the same form of ''be'' as the question. The question uses ''Was he'', so the answer is ''he was''. မေးခွန်းက ''Was he'' ဖြစ်တဲ့အတွက် အဖြေက ''he was'' ဖြစ်ရပါမယ်။","points":1},{"id":243,"question":"Was he at home last night? No, ________.","options":["he wasn''t","he weren''t","he isn''t"],"answer":"he wasn''t","explanation":"Negative short answer uses the negative form of ''be''. The question uses ''Was he'', so the negative answer is ''he wasn''t''. မေးခွန်းက ''Was he'' ဖြစ်တဲ့အတွက် အဖြေက ''he wasn''t'' ဖြစ်ရပါမယ်။","points":1},{"id":244,"question":"Were you at school yesterday? Yes, ________.","options":["I was","I were","I am"],"answer":"I was","explanation":"When answering a question about ''you'', we change ''you'' to ''I'' in the answer. The question uses ''Were you'', so the answer is ''I was''. ''you'' အကြောင်း မေးတဲ့အခါ အဖြေမှာ ''I'' ကိုသုံးပါ။","points":1},{"id":245,"question":"Were you at school yesterday? No, ________.","options":["I wasn''t","I weren''t","I isn''t"],"answer":"I wasn''t","explanation":"When answering a question about ''you'', we change ''you'' to ''I'' in the answer. The question uses ''Were you'', so the negative answer is ''I wasn''t''. ''you'' အကြောင်း မေးတဲ့အခါ အဖြေမှာ ''I'' ကိုသုံးပါ။","points":1},{"id":246,"question":"Will she be happy tomorrow? Yes, ________.","options":["she will","she is","she was"],"answer":"she will","explanation":"Short answer uses the same auxiliary verb as the question. The question uses ''Will she'', so the answer is ''she will''. မေးခွန်းက ''Will she'' ဖြစ်တဲ့အတွက် အဖြေက ''she will'' ဖြစ်ရပါမယ်။","points":1},{"id":247,"question":"Will she be happy tomorrow? No, ________.","options":["she won''t","she isn''t","she wasn''t"],"answer":"she won''t","explanation":"Negative short answer uses the negative form of the auxiliary verb. The question uses ''Will she'', so the negative answer is ''she won''t''. မေးခွန်းက ''Will she'' ဖြစ်တဲ့အတွက် အဖြေက ''she won''t'' ဖြစ်ရပါမယ်။","points":1},{"id":248,"question":"Will we be at home tomorrow? Yes, ________.","options":["we will","we are","we were"],"answer":"we will","explanation":"Short answer uses the same auxiliary verb as the question. The question uses ''Will we'', so the answer is ''we will''. မေးခွန်းက ''Will we'' ဖြစ်တဲ့အတွက် အဖြေက ''we will'' ဖြစ်ရပါမယ်။","points":1},{"id":249,"question":"Will we be at home tomorrow? No, ________.","options":["we won''t","we aren''t","we weren''t"],"answer":"we won''t","explanation":"Negative short answer uses the negative form of the auxiliary verb. The question uses ''Will we'', so the negative answer is ''we won''t''. မေးခွန်းက ''Will we'' ဖြစ်တဲ့အတွက် အဖြေက ''we won''t'' ဖြစ်ရပါမယ်။","points":1},{"id":250,"question":"Will you be late next time? Yes, ________.","options":["I will","I am","I was"],"answer":"I will","explanation":"When answering a question about ''you'', we change ''you'' to ''I'' in the answer. The question uses ''Will you'', so the answer is ''I will''. ''you'' အကြောင်း မေးတဲ့အခါ အဖြေမှာ ''I'' ကိုသုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00002002-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 2), 'unit2-ex3', 'multiple_choice', 'Choose the correct English translation.', '[{"id":251,"question":"ကျွန်မ ဆရာဝန်တစ်ယောက်ပါ။ (I / a doctor)","options":["I am a doctor.","I is a doctor.","I are a doctor."],"answer":"I am a doctor.","explanation":"With ''I'', we use ''am''. ''I am a doctor'' is the correct translation. ''I'' နဲ့ ''am'' ကိုသုံးပါ။","points":2},{"id":252,"question":"သူ ဆရာတစ်ယောက်ပါ။ (He / a teacher)","options":["He is a teacher.","He am a teacher.","He are a teacher."],"answer":"He is a teacher.","explanation":"With ''he'', we use ''is''. ''He is a teacher'' is the correct translation. ''He'' နဲ့ ''is'' ကိုသုံးပါ။","points":2},{"id":253,"question":"သူမ လှပတယ်။ (She / beautiful)","options":["She is beautiful.","She am beautiful.","She are beautiful."],"answer":"She is beautiful.","explanation":"With ''she'', we use ''is''. ''She is beautiful'' is the correct translation. ''She'' နဲ့ ''is'' ကိုသုံးပါ။","points":2},{"id":254,"question":"ငါတို့ ပန်းခြံထဲမှာ ရှိတယ်။ (We / in the park)","options":["We are in the park.","We is in the park.","We am in the park."],"answer":"We are in the park.","explanation":"With ''we'', we use ''are''. ''We are in the park'' is the correct translation. ''We'' နဲ့ ''are'' ကိုသုံးပါ။","points":2},{"id":255,"question":"မင်း ငါ့သူငယ်ချင်းပါ။ (You / my friend)","options":["You are my friend.","You is my friend.","You am my friend."],"answer":"You are my friend.","explanation":"With ''you'', we use ''are''. ''You are my friend'' is the correct translation. ''You'' နဲ့ ''are'' ကိုသုံးပါ။","points":2},{"id":256,"question":"သူတို့ ဆရာဝန်တွေပါ။ (They / doctors)","options":["They are doctors.","They is doctors.","They am doctors."],"answer":"They are doctors.","explanation":"With ''they'', we use ''are''. ''They are doctors'' is the correct translation. ''They'' နဲ့ ''are'' ကိုသုံးပါ။","points":2},{"id":257,"question":"မနေ့ညက ကျွန်မ အိမ်မှာ ရှိခဲ့တယ်။ (I / at home / last night)","options":["I was at home last night.","I were at home last night.","I am at home last night."],"answer":"I was at home last night.","explanation":"With ''I'' in past tense, we use ''was''. ''Last night'' indicates past time. ''I'' နဲ့ အတိတ်ကာလမှာ ''was'' ကိုသုံးပါ။","points":2},{"id":258,"question":"မနေ့က သူ ကျောင်းသားတစ်ယောက်ပါ။ (He / a student / yesterday)","options":["He was a student yesterday.","He were a student yesterday.","He is a student yesterday."],"answer":"He was a student yesterday.","explanation":"With ''he'' in past tense, we use ''was''. ''Yesterday'' indicates past time. ''He'' နဲ့ အတိတ်ကာလမှာ ''was'' ကိုသုံးပါ။","points":2},{"id":259,"question":"မနေ့ညက သူမ ပင်ပန်းနေတယ်။ (She / tired / last night)","options":["She was tired last night.","She were tired last night.","She is tired last night."],"answer":"She was tired last night.","explanation":"With ''she'' in past tense, we use ''was''. ''Last night'' indicates past time. ''She'' နဲ့ အတိတ်ကာလမှာ ''was'' ကိုသုံးပါ။","points":2},{"id":260,"question":"မနေ့က ငါတို့ ကျောင်းမှာ ရှိခဲ့တယ်။ (We / at school / yesterday)","options":["We were at school yesterday.","We was at school yesterday.","We are at school yesterday."],"answer":"We were at school yesterday.","explanation":"With ''we'' in past tense, we use ''were''. ''Yesterday'' indicates past time. ''We'' နဲ့ အတိတ်ကာလမှာ ''were'' ကိုသုံးပါ။","points":2},{"id":261,"question":"မနေ့က မင်း ပျော်ရွှင်ခဲ့တယ်။ (You / happy / yesterday)","options":["You were happy yesterday.","You was happy yesterday.","You are happy yesterday."],"answer":"You were happy yesterday.","explanation":"With ''you'' in past tense, we use ''were''. ''Yesterday'' indicates past time. ''You'' နဲ့ အတိတ်ကာလမှာ ''were'' ကိုသုံးပါ။","points":2},{"id":262,"question":"ပြီးခဲ့တဲ့အပတ်က သူတို့ စျေးမှာ ရှိခဲ့တယ်။ (They / at the market / last week)","options":["They were at the market last week.","They was at the market last week.","They are at the market last week."],"answer":"They were at the market last week.","explanation":"With ''they'' in past tense, we use ''were''. ''Last week'' indicates past time. ''They'' နဲ့ အတိတ်ကာလမှာ ''were'' ကိုသုံးပါ။","points":2},{"id":263,"question":"နောက်နှစ် ကျွန်မ ဆရာဝန်ဖြစ်မယ်။ (I / a doctor / next year)","options":["I will be a doctor next year.","I am a doctor next year.","I was a doctor next year."],"answer":"I will be a doctor next year.","explanation":"With ''I'' in future tense, we use ''will be''. ''Next year'' indicates future time. ''I'' နဲ့ အနာဂတ်ကာလမှာ ''will be'' ကိုသုံးပါ။","points":2},{"id":264,"question":"မနက်ဖန် ငါတို့ အိမ်မှာ ရှိမယ်။ (We / at home / tomorrow)","options":["We will be at home tomorrow.","We are at home tomorrow.","We were at home tomorrow."],"answer":"We will be at home tomorrow.","explanation":"With ''we'' in future tense, we use ''will be''. ''Tomorrow'' indicates future time. ''We'' နဲ့ အနာဂတ်ကာလမှာ ''will be'' ကိုသုံးပါ။","points":2},{"id":265,"question":"မကြာခင် သူ ရောက်လာမယ်။ (He / here / soon)","options":["He will be here soon.","He is here soon.","He was here soon."],"answer":"He will be here soon.","explanation":"With ''he'' in future tense, we use ''will be''. ''Soon'' indicates future time. ''He'' နဲ့ အနာဂတ်ကာလမှာ ''will be'' ကိုသုံးပါ။","points":2},{"id":266,"question":"မနက်ဖန် သူမ ပျော်ရွှင်မယ်။ (She / happy / tomorrow)","options":["She will be happy tomorrow.","She is happy tomorrow.","She was happy tomorrow."],"answer":"She will be happy tomorrow.","explanation":"With ''she'' in future tense, we use ''will be''. ''Tomorrow'' indicates future time. ''She'' နဲ့ အနာဂတ်ကာလမှာ ''will be'' ကိုသုံးပါ။","points":2},{"id":267,"question":"နောက်အပတ် ပူနွေးမယ်။ (It / hot / next week)","options":["It will be hot next week.","It is hot next week.","It was hot next week."],"answer":"It will be hot next week.","explanation":"With ''it'' in future tense, we use ''will be''. ''Next week'' indicates future time. ''It'' နဲ့ အနာဂတ်ကာလမှာ ''will be'' ကိုသုံးပါ။","points":2},{"id":268,"question":"နောက်တနင်္လာနေ့ သူတို့ ကျောင်းမှာ ရှိမယ်။ (They / at school / next Monday)","options":["They will be at school next Monday.","They are at school next Monday.","They were at school next Monday."],"answer":"They will be at school next Monday.","explanation":"With ''they'' in future tense, we use ''will be''. ''Next Monday'' indicates future time. ''They'' နဲ့ အနာဂတ်ကာလမှာ ''will be'' ကိုသုံးပါ။","points":2},{"id":269,"question":"နောက်တစ်ကြိမ် မင်း နောက်ကျမယ်။ (You / late / next time)","options":["You will be late next time.","You are late next time.","You were late next time."],"answer":"You will be late next time.","explanation":"With ''you'' in future tense, we use ''will be''. ''Next time'' indicates future time. ''You'' နဲ့ အနာဂတ်ကာလမှာ ''will be'' ကိုသုံးပါ။","points":2},{"id":270,"question":"ကျွန်မ ဆရာဝန်မဟုတ်ဘူး။ (I / not / a doctor)","options":["I am not a doctor.","I is not a doctor.","I are not a doctor."],"answer":"I am not a doctor.","explanation":"With ''I'', we use ''am not'' for negative. ''I am not a doctor'' is the correct translation. ''I'' နဲ့ ငြင်းဆိုပုံ ''am not'' ဖြစ်ပါတယ်။","points":2},{"id":271,"question":"သူမ လှမဟုတ်ဘူး။ (She / not / beautiful)","options":["She is not beautiful.","She am not beautiful.","She are not beautiful."],"answer":"She is not beautiful.","explanation":"With ''she'', we use ''is not'' for negative. ''She is not beautiful'' is the correct translation. ''She'' နဲ့ ငြင်းဆိုပုံ ''is not'' ဖြစ်ပါတယ်။","points":2},{"id":272,"question":"သူတို့ အိမ်မှာ မရှိဘူး။ (They / not / at home)","options":["They are not at home.","They is not at home.","They am not at home."],"answer":"They are not at home.","explanation":"With ''they'', we use ''are not'' for negative. ''They are not at home'' is the correct translation. ''They'' နဲ့ ငြင်းဆိုပုံ ''are not'' ဖြစ်ပါတယ်။","points":2},{"id":273,"question":"ကျွန်မ ဆရာဝန်လား။ (I / a doctor)","options":["Am I a doctor?","Is I a doctor?","Are I a doctor?"],"answer":"Am I a doctor?","explanation":"With ''I'' in interrogative, we use ''Am I...?''. ''Am I a doctor?'' is the correct translation. ''I'' နဲ့ မေးခွန်းပုံ ''Am I...?'' ဖြစ်ပါတယ်။","points":2},{"id":274,"question":"သူ ဆရာလား။ (He / a teacher)","options":["Is he a teacher?","Am he a teacher?","Are he a teacher?"],"answer":"Is he a teacher?","explanation":"With ''he'' in interrogative, we use ''Is he...?''. ''Is he a teacher?'' is the correct translation. ''He'' နဲ့ မေးခွန်းပုံ ''Is he...?'' ဖြစ်ပါတယ်။","points":2},{"id":275,"question":"သူတို့ ပန်းခြံထဲမှာ ရှိလား။ (They / in the park)","options":["Are they in the park?","Is they in the park?","Am they in the park?"],"answer":"Are they in the park?","explanation":"With ''they'' in interrogative, we use ''Are they...?''. ''Are they in the park?'' is the correct translation. ''They'' နဲ့ မေးခွန်းပုံ ''Are they...?'' ဖြစ်ပါတယ်။","points":2}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

