INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00003000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 3), 'unit3-ex1', 'multiple_choice', 'Choose the correct form of ''have'' to complete each sentence.', '[{"id":301,"question":"I ________ a car.","options":["have","has","had"],"answer":"have","explanation":"With ''I'', we use ''have''. ''I have'' is the correct Simple Present form for first person singular. ''I'' နဲ့ ''have'' ကိုသုံးပါ။","points":1},{"id":302,"question":"She ________ many pencils.","options":["have","has","had"],"answer":"has","explanation":"With ''she'', we use ''has''. ''Has'' is the correct Simple Present form for third person singular. ''She'' နဲ့ ''has'' ကိုသုံးပါ။","points":1},{"id":303,"question":"We ________ lots of books.","options":["have","has","had"],"answer":"have","explanation":"With ''we'', we use ''have''. ''We have'' is the correct Simple Present form for first person plural. ''We'' နဲ့ ''have'' ကိုသုံးပါ။","points":1},{"id":304,"question":"He ________ his own diary.","options":["have","has","had"],"answer":"has","explanation":"With ''he'', we use ''has''. ''He has'' is the correct Simple Present form for third person singular. ''He'' နဲ့ ''has'' ကိုသုံးပါ။","points":1},{"id":305,"question":"They ________ many clothes.","options":["have","has","had"],"answer":"have","explanation":"With ''they'', we use ''have''. ''They have'' is the correct Simple Present form for third person plural. ''They'' နဲ့ ''have'' ကိုသုံးပါ။","points":1},{"id":306,"question":"I ________ a car before.","options":["have","has","had"],"answer":"had","explanation":"''Before'' indicates past time, so we use ''had'' (Simple Past). ''Before'' ဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် ''had'' ကိုသုံးပါ။","points":1},{"id":307,"question":"She ________ many friends last week.","options":["have","has","had"],"answer":"had","explanation":"''Last week'' indicates past time, so we use ''had'' (Simple Past). ''Last week'' ဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် ''had'' ကိုသုံးပါ။","points":1},{"id":308,"question":"We ________ a big house next year.","options":["have","has","will have"],"answer":"will have","explanation":"''Next year'' indicates future time, so we use ''will have''. ''Next year'' ဆိုတာ အနာဂတ်ကာလဖြစ်တဲ့အတွက် ''will have'' ကိုသုံးပါ။","points":1},{"id":309,"question":"He ________ a new phone yesterday.","options":["have","has","had"],"answer":"had","explanation":"''Yesterday'' indicates past time, so we use ''had'' (Simple Past). ''Yesterday'' ဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် ''had'' ကိုသုံးပါ။","points":1},{"id":310,"question":"You ________ a beautiful garden now.","options":["have","has","will have"],"answer":"have","explanation":"With ''you'', we use ''have''. ''Now'' indicates present time. ''You'' နဲ့ ''have'' ကိုသုံးပါ။ ''Now'' ဆိုတာ လက်ရှိကာလဖြစ်ပါတယ်။","points":1},{"id":311,"question":"It ________ a long history.","options":["have","has","had"],"answer":"has","explanation":"With ''it'', we use ''has''. ''It has'' is the correct Simple Present form for third person singular. ''It'' နဲ့ ''has'' ကိုသုံးပါ။","points":1},{"id":312,"question":"They ________ lots of money two days ago.","options":["have","has","had"],"answer":"had","explanation":"''Two days ago'' indicates past time, so we use ''had'' (Simple Past). ''Two days ago'' ဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် ''had'' ကိုသုံးပါ။","points":1},{"id":313,"question":"I ________ three brothers.","options":["have","has","had"],"answer":"have","explanation":"With ''I'', we use ''have''. ''I have'' is the correct Simple Present form. ''I'' နဲ့ ''have'' ကိုသုံးပါ။","points":1},{"id":314,"question":"She ________ a dog every day.","options":["have","has","had"],"answer":"has","explanation":"With ''she'', we use ''has''. ''Every day'' indicates a regular habit. ''She'' နဲ့ ''has'' ကိုသုံးပါ။","points":1},{"id":315,"question":"We ________ a new car last month.","options":["have","has","had"],"answer":"had","explanation":"''Last month'' indicates past time, so we use ''had'' (Simple Past). ''Last month'' ဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် ''had'' ကိုသုံးပါ။","points":1},{"id":316,"question":"He ________ a car next year.","options":["have","has","will have"],"answer":"will have","explanation":"''Next year'' indicates future time, so we use ''will have''. ''Next year'' ဆိုတာ အနာဂတ်ကာလဖြစ်တဲ့အတွက် ''will have'' ကိုသုံးပါ။","points":1},{"id":317,"question":"You ________ a bicycle when you were young.","options":["have","has","had"],"answer":"had","explanation":"''When you were young'' indicates past time, so we use ''had'' (Simple Past). ''When you were young'' ဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် ''had'' ကိုသုံးပါ။","points":1},{"id":318,"question":"They ________ a meeting tomorrow.","options":["have","has","will have"],"answer":"will have","explanation":"''Tomorrow'' indicates future time, so we use ''will have''. ''Tomorrow'' ဆိုတာ အနာဂတ်ကာလဖြစ်တဲ့အတွက် ''will have'' ကိုသုံးပါ။","points":1},{"id":319,"question":"It ________ a lot of rain yesterday.","options":["have","has","had"],"answer":"had","explanation":"''Yesterday'' indicates past time, so we use ''had'' (Simple Past). ''Yesterday'' ဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် ''had'' ကိုသုံးပါ။","points":1},{"id":320,"question":"I ________ two sisters.","options":["have","has","had"],"answer":"have","explanation":"With ''I'', we use ''have''. ''I have'' is the correct Simple Present form. ''I'' နဲ့ ''have'' ကိုသုံးပါ။","points":1},{"id":321,"question":"She ________ a beautiful dress.","options":["have","has","had"],"answer":"has","explanation":"With ''she'', we use ''has''. ''She has'' is the correct Simple Present form. ''She'' နဲ့ ''has'' ကိုသုံးပါ။","points":1},{"id":322,"question":"He ________ a new job last week.","options":["have","has","had"],"answer":"had","explanation":"''Last week'' indicates past time, so we use ''had'' (Simple Past). ''Last week'' ဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် ''had'' ကိုသုံးပါ။","points":1},{"id":323,"question":"We ________ enough time now.","options":["have","has","had"],"answer":"have","explanation":"With ''we'', we use ''have''. ''Now'' indicates present time. ''We'' နဲ့ ''have'' ကိုသုံးပါ။","points":1},{"id":324,"question":"They ________ a holiday next month.","options":["have","has","will have"],"answer":"will have","explanation":"''Next month'' indicates future time, so we use ''will have''. ''Next month'' ဆိုတာ အနာဂတ်ကာလဖြစ်တဲ့အတွက် ''will have'' ကိုသုံးပါ။","points":1},{"id":325,"question":"You ________ a pen yesterday.","options":["have","has","had"],"answer":"had","explanation":"''Yesterday'' indicates past time, so we use ''had'' (Simple Past). ''Yesterday'' ဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် ''had'' ကိုသုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00003001-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 3), 'unit3-ex2', 'multiple_choice', 'Choose the correct short answer.', '[{"id":326,"question":"Do you have a car? Yes, ________.","options":["I do","I did","I will"],"answer":"I do","explanation":"The question uses ''Do'' (Simple Present), so the short answer must be ''I do''. မေးခွန်းက ''Do'' (Simple Present) သုံးထားတဲ့အတွက် အဖြေက ''I do'' ဖြစ်ရပါမယ်။","points":1},{"id":327,"question":"Do you have a car? No, ________.","options":["I don''t","I didn''t","I won''t"],"answer":"I don''t","explanation":"The question uses ''Do'' (Simple Present), so the short negative answer must be ''I don''t''. မေးခွန်းက ''Do'' (Simple Present) သုံးထားတဲ့အတွက် အဖြေက ''I don''t'' ဖြစ်ရပါမယ်။","points":1},{"id":328,"question":"Did you have a car before? Yes, ________.","options":["I did","I do","I will"],"answer":"I did","explanation":"The question uses ''Did'' (Simple Past), so the short answer must be ''I did''. မေးခွန်းက ''Did'' (Simple Past) သုံးထားတဲ့အတွက် အဖြေက ''I did'' ဖြစ်ရပါမယ်။","points":1},{"id":329,"question":"Did you have a car before? No, ________.","options":["I didn''t","I don''t","I won''t"],"answer":"I didn''t","explanation":"The question uses ''Did'' (Simple Past), so the short negative answer must be ''I didn''t''. မေးခွန်းက ''Did'' (Simple Past) သုံးထားတဲ့အတွက် အဖြေက ''I didn''t'' ဖြစ်ရပါမယ်။","points":1},{"id":330,"question":"Will you have a car next year? Yes, ________.","options":["I will","I do","I did"],"answer":"I will","explanation":"The question uses ''Will'' (Simple Future), so the short answer must be ''I will''. မေးခွန်းက ''Will'' (Simple Future) သုံးထားတဲ့အတွက် အဖြေက ''I will'' ဖြစ်ရပါမယ်။","points":1},{"id":331,"question":"Will you have a car next year? No, ________.","options":["I won''t","I don''t","I didn''t"],"answer":"I won''t","explanation":"The question uses ''Will'' (Simple Future), so the short negative answer must be ''I won''t''. မေးခွန်းက ''Will'' (Simple Future) သုံးထားတဲ့အတွက် အဖြေက ''I won''t'' ဖြစ်ရပါမယ်။","points":1},{"id":332,"question":"Has she been here for twenty minutes? Yes, ________.","options":["she has","she have","she had"],"answer":"she has","explanation":"The question uses ''Has'' (Present Perfect), so the short answer must be ''she has''. မေးခွန်းက ''Has'' (Present Perfect) သုံးထားတဲ့အတွက် အဖြေက ''she has'' ဖြစ်ရပါမယ်။","points":1},{"id":333,"question":"Has she been here for twenty minutes? No, ________.","options":["she hasn''t","she haven''t","she hadn''t"],"answer":"she hasn''t","explanation":"The question uses ''Has'' (Present Perfect), so the short negative answer must be ''she hasn''t''. မေးခွန်းက ''Has'' (Present Perfect) သုံးထားတဲ့အတွက် အဖြေက ''she hasn''t'' ဖြစ်ရပါမယ်။","points":1},{"id":334,"question":"Had he met her before the party? Yes, ________.","options":["he had","he has","he did"],"answer":"he had","explanation":"The question uses ''Had'' (Past Perfect), so the short answer must be ''he had''. မေးခွန်းက ''Had'' (Past Perfect) သုံးထားတဲ့အတွက် အဖြေက ''he had'' ဖြစ်ရပါမယ်။","points":1},{"id":335,"question":"Had he met her before the party? No, ________.","options":["he hadn''t","he hasn''t","he didn''t"],"answer":"he hadn''t","explanation":"The question uses ''Had'' (Past Perfect), so the short negative answer must be ''he hadn''t''. မေးခွန်းက ''Had'' (Past Perfect) သုံးထားတဲ့အတွက် အဖြေက ''he hadn''t'' ဖြစ်ရပါမယ်။","points":1},{"id":336,"question":"Will they have finished by tomorrow? Yes, ________.","options":["they will","they have","they had"],"answer":"they will","explanation":"The question uses ''Will'' (Future Perfect), so the short answer must be ''they will''. မေးခွန်းက ''Will'' (Future Perfect) သုံးထားတဲ့အတွက် အဖြေက ''they will'' ဖြစ်ရပါမယ်။","points":1},{"id":337,"question":"Will they have finished by tomorrow? No, ________.","options":["they won''t","they haven''t","they hadn''t"],"answer":"they won''t","explanation":"The question uses ''Will'' (Future Perfect), so the short negative answer must be ''they won''t''. မေးခွန်းက ''Will'' (Future Perfect) သုံးထားတဲ့အတွက် အဖြေက ''they won''t'' ဖြစ်ရပါမယ်။","points":1},{"id":338,"question":"Do we have enough time? Yes, ________.","options":["we do","we did","we will"],"answer":"we do","explanation":"The question uses ''Do'' (Simple Present), so the short answer must be ''we do''. မေးခွန်းက ''Do'' (Simple Present) သုံးထားတဲ့အတွက် အဖြေက ''we do'' ဖြစ်ရပါမယ်။","points":1},{"id":339,"question":"Does he have a bike? Yes, ________.","options":["he does","he do","he has"],"answer":"he does","explanation":"The question uses ''Does'' (Simple Present, he/she/it), so the short answer must be ''he does''. မေးခွန်းက ''Does'' (Simple Present, he/she/it) သုံးထားတဲ့အတွက် အဖြေက ''he does'' ဖြစ်ရပါမယ်။","points":1},{"id":340,"question":"Does he have a bike? No, ________.","options":["he doesn''t","he don''t","he hasn''t"],"answer":"he doesn''t","explanation":"The question uses ''Does'' (Simple Present, he/she/it), so the short negative answer must be ''he doesn''t''. မေးခွန်းက ''Does'' (Simple Present, he/she/it) သုံးထားတဲ့အတွက် အဖြေက ''he doesn''t'' ဖြစ်ရပါမယ်။","points":1},{"id":341,"question":"Did they have a party last night? Yes, ________.","options":["they did","they do","they will"],"answer":"they did","explanation":"The question uses ''Did'' (Simple Past), so the short answer must be ''they did''. မေးခွန်းက ''Did'' (Simple Past) သုံးထားတဲ့အတွက် အဖြေက ''they did'' ဖြစ်ရပါမယ်။","points":1},{"id":342,"question":"Did they have a party last night? No, ________.","options":["they didn''t","they don''t","they won''t"],"answer":"they didn''t","explanation":"The question uses ''Did'' (Simple Past), so the short negative answer must be ''they didn''t''. မေးခွန်းက ''Did'' (Simple Past) သုံးထားတဲ့အတွက် အဖြေက ''they didn''t'' ဖြစ်ရပါမယ်။","points":1},{"id":343,"question":"Will she have a new job next month? Yes, ________.","options":["she will","she does","she did"],"answer":"she will","explanation":"The question uses ''Will'' (Simple Future), so the short answer must be ''she will''. မေးခွန်းက ''Will'' (Simple Future) သုံးထားတဲ့အတွက် အဖြေက ''she will'' ဖြစ်ရပါမယ်။","points":1},{"id":344,"question":"Will she have a new job next month? No, ________.","options":["she won''t","she doesn''t","she didn''t"],"answer":"she won''t","explanation":"The question uses ''Will'' (Simple Future), so the short negative answer must be ''she won''t''. မေးခွန်းက ''Will'' (Simple Future) သုံးထားတဲ့အတွက် အဖြေက ''she won''t'' ဖြစ်ရပါမယ်။","points":1},{"id":345,"question":"Have they visited Florida? Yes, ________.","options":["they have","they had","they did"],"answer":"they have","explanation":"The question uses ''Have'' (Present Perfect), so the short answer must be ''they have''. မေးခွန်းက ''Have'' (Present Perfect) သုံးထားတဲ့အတွက် အဖြေက ''they have'' ဖြစ်ရပါမယ်။","points":1},{"id":346,"question":"Have they visited Florida? No, ________.","options":["they haven''t","they hadn''t","they didn''t"],"answer":"they haven''t","explanation":"The question uses ''Have'' (Present Perfect), so the short negative answer must be ''they haven''t''. မေးခွန်းက ''Have'' (Present Perfect) သုံးထားတဲ့အတွက် အဖြေက ''they haven''t'' ဖြစ်ရပါမယ်။","points":1},{"id":347,"question":"Had she established her company before 2008? Yes, ________.","options":["she had","she has","she did"],"answer":"she had","explanation":"The question uses ''Had'' (Past Perfect), so the short answer must be ''she had''. မေးခွန်းက ''Had'' (Past Perfect) သုံးထားတဲ့အတွက် အဖြေက ''she had'' ဖြစ်ရပါမယ်။","points":1},{"id":348,"question":"Had she established her company before 2008? No, ________.","options":["she hadn''t","she hasn''t","she didn''t"],"answer":"she hadn''t","explanation":"The question uses ''Had'' (Past Perfect), so the short negative answer must be ''she hadn''t''. မေးခွန်းက ''Had'' (Past Perfect) သုံးထားတဲ့အတွက် အဖြေက ''she hadn''t'' ဖြစ်ရပါမယ်။","points":1},{"id":349,"question":"Will we have finished by next week? Yes, ________.","options":["we will","we have","we had"],"answer":"we will","explanation":"The question uses ''Will'' (Future Perfect), so the short answer must be ''we will''. မေးခွန်းက ''Will'' (Future Perfect) သုံးထားတဲ့အတွက် အဖြေက ''we will'' ဖြစ်ရပါမယ်။","points":1},{"id":350,"question":"Will we have finished by next week? No, ________.","options":["we won''t","we haven''t","we hadn''t"],"answer":"we won''t","explanation":"The question uses ''Will'' (Future Perfect), so the short negative answer must be ''we won''t''. မေးခွန်းက ''Will'' (Future Perfect) သုံးထားတဲ့အတွက် အဖြေက ''we won''t'' ဖြစ်ရပါမယ်။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00003002-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 3), 'unit3-ex3', 'multiple_choice', 'Choose the correct English translation.', '[{"id":351,"question":"ကျွန်မ ကားတစ်စီး ရှိတယ်။ (I / a car)","options":["I have a car.","I has a car.","I had a car."],"answer":"I have a car.","explanation":"Simple Present Affirmative: Subject + have. ''တယ်'' indicates present affirmative. With ''I'', we use ''have''. Simple Present အတည်ပြုပုံ - Subject + have။","points":2},{"id":352,"question":"အရင်က ကျွန်မ ကားတစ်စီး ရှိခဲ့တယ်။ (I / a car / before)","options":["I had a car before.","I have a car before.","I will have a car before."],"answer":"I had a car before.","explanation":"Simple Past Affirmative: Subject + had. ''ခဲ့တယ်'' indicates past. ''Before'' indicates past time. Simple Past အတည်ပြုပုံ - Subject + had။","points":2},{"id":353,"question":"နောက်နှစ် ကျွန်မ ကားတစ်စီး ရှိမယ်။ (I / a car / next year)","options":["I will have a car next year.","I have a car next year.","I had a car next year."],"answer":"I will have a car next year.","explanation":"Simple Future Affirmative: Subject + will have. ''မယ်'' and ''next year'' indicate future. Simple Future အတည်ပြုပုံ - Subject + will have။","points":2},{"id":354,"question":"သူမ ဘေလွင့်တံ အများကြီး ရှိတယ်။ (She / many pencils)","options":["She has many pencils.","She have many pencils.","She had many pencils."],"answer":"She has many pencils.","explanation":"Simple Present Affirmative: Subject + has. ''တယ်'' indicates present affirmative. With ''she'', we use ''has''. Simple Present အတည်ပြုပုံ - Subject + has။","points":2},{"id":355,"question":"သူ ကိုယ်ပိုင် Diary ရှိတယ်။ (He / his own diary)","options":["He has his own diary.","He have his own diary.","He had his own diary."],"answer":"He has his own diary.","explanation":"Simple Present Affirmative: Subject + has. ''တယ်'' indicates present affirmative. With ''he'', we use ''has''. Simple Present အတည်ပြုပုံ - Subject + has။","points":2},{"id":356,"question":"သူတို့ အဝတ်တွေ အများကြီး ရှိတယ်။ (They / many clothes)","options":["They have many clothes.","They has many clothes.","They had many clothes."],"answer":"They have many clothes.","explanation":"Simple Present Affirmative: Subject + have. ''တယ်'' indicates present affirmative. With ''they'', we use ''have''. Simple Present အတည်ပြုပုံ - Subject + have။","points":2},{"id":357,"question":"ငါတို့ စာအုပ်တွေ အများကြီး ရှိတယ်။ (We / lots of books)","options":["We have lots of books.","We has lots of books.","We had lots of books."],"answer":"We have lots of books.","explanation":"Simple Present Affirmative: Subject + have. ''တယ်'' indicates present affirmative. With ''we'', we use ''have''. Simple Present အတည်ပြုပုံ - Subject + have။","points":2},{"id":358,"question":"မနေ့က သူ ဖုန်းအသစ် ရှိခဲ့တယ်။ (He / a new phone / yesterday)","options":["He had a new phone yesterday.","He has a new phone yesterday.","He will have a new phone yesterday."],"answer":"He had a new phone yesterday.","explanation":"Simple Past Affirmative: Subject + had. ''ခဲ့တယ်'' indicates past. ''Yesterday'' indicates past time. Simple Past အတည်ပြုပုံ - Subject + had။","points":2},{"id":359,"question":"နောက်နှစ် သူတို့ ကားကြီးတစ်စီး ရှိမယ်။ (They / a big car / next year)","options":["They will have a big car next year.","They have a big car next year.","They had a big car next year."],"answer":"They will have a big car next year.","explanation":"Simple Future Affirmative: Subject + will have. ''မယ်'' and ''next year'' indicate future. Simple Future အတည်ပြုပုံ - Subject + will have။","points":2},{"id":360,"question":"မင်း ကား ရှိလား။ (you / a car)","options":["Do you have a car?","Does you have a car?","Did you have a car?"],"answer":"Do you have a car?","explanation":"Simple Present Interrogative: Do + subject + have? ''လား'' indicates present question. With ''you'', we use ''Do''. Simple Present မေးခွန်းပုံ - Do + subject + have?","points":2},{"id":361,"question":"သူ ကား မရှိဘူး။ (He / a car)","options":["He doesn''t have a car.","He don''t have a car.","He hasn''t a car."],"answer":"He doesn''t have a car.","explanation":"Simple Present Negative: Subject + doesn''t have. ''ဘူး'' indicates present negative. With ''he'', we use ''doesn''t''. Simple Present ငြင်းဆိုပုံ - Subject + doesn''t have။","points":2},{"id":362,"question":"ငါတို့ မနေ့က ပါတီ မရှိခဲ့ဘူး။ (We / a party / yesterday)","options":["We didn''t have a party yesterday.","We don''t have a party yesterday.","We won''t have a party yesterday."],"answer":"We didn''t have a party yesterday.","explanation":"Simple Past Negative: Subject + didn''t have. ''ခဲ့ဘူး'' indicates past negative. ''Yesterday'' indicates past time. Simple Past ငြင်းဆိုပုံ - Subject + didn''t have။","points":2},{"id":363,"question":"သူမ မနက်ဖန် အလုပ်အသစ် ရှိမယ်။ (She / a new job / tomorrow)","options":["She will have a new job tomorrow.","She has a new job tomorrow.","She had a new job tomorrow."],"answer":"She will have a new job tomorrow.","explanation":"Simple Future Affirmative: Subject + will have. ''မယ်'' and ''tomorrow'' indicate future. Simple Future အတည်ပြုပုံ - Subject + will have။","points":2},{"id":364,"question":"သူတို့ Florida ကို သွားပြီးပြီ။ (They / visited Florida)","options":["They have visited Florida.","They has visited Florida.","They had visited Florida."],"answer":"They have visited Florida.","explanation":"Present Perfect: Subject + have + V3. ''ပြီ'' indicates completed action. With ''they'', we use ''have''. Present Perfect - Subject + have + V3။","points":2},{"id":365,"question":"သူမ မိနစ်နှစ်ဆယ်ကတည်းက ဒီမှာ ရှိနေတယ်။ (She / here / twenty minutes)","options":["She has been here for twenty minutes.","She have been here for twenty minutes.","She had been here for twenty minutes."],"answer":"She has been here for twenty minutes.","explanation":"Present Perfect: Subject + has + V3. ''ကတည်းက'' indicates an action that started in the past and continues to the present. With ''she'', we use ''has''. Present Perfect - Subject + has + V3။","points":2},{"id":366,"question":"ငါတို့ သူ့ကို နာမည်ကြီးမတိုင်ခင် တွေ့ခဲ့ပြီ။ (We / him / before he became famous)","options":["We had met him before he became famous.","We have met him before he became famous.","We will have met him before he became famous."],"answer":"We had met him before he became famous.","explanation":"Past Perfect: Subject + had + V3. ''ပြီ'' and ''before he became famous'' indicate an action completed before another past action. Past Perfect - Subject + had + V3။","points":2},{"id":367,"question":"သူ ကွန်ပျူတာ ပျက်ခင် စာရွက်ကို ကူးယူပြီးပြီ။ (Tom / copied / before the computer crashed)","options":["Tom had copied his document before the computer crashed.","Tom has copied his document before the computer crashed.","Tom will have copied his document before the computer crashed."],"answer":"Tom had copied his document before the computer crashed.","explanation":"Past Perfect: Subject + had + V3. ''ပြီးပြီ'' and ''before the computer crashed'' indicate an action completed before another past action. Past Perfect - Subject + had + V3။","points":2},{"id":368,"question":"ငါတို့ ဒီစီမံကိန်းကို ပြီးအောင်လုပ်ပြီးမယ်။ (We / finished / our project)","options":["We will have finished our project.","We have finished our project.","We had finished our project."],"answer":"We will have finished our project.","explanation":"Future Perfect: Subject + will have + V3. ''ပြီးမယ်'' indicates a future completed action. Future Perfect - Subject + will have + V3။","points":2},{"id":369,"question":"မင်း အင်္ဂါနေ့မတိုင်ခင် စာတစ်စောင် ပို့ပြီးပြီမယ်။ (You / sent the document / by Tuesday)","options":["You will have sent the document by Tuesday.","You have sent the document by Tuesday.","You had sent the document by Tuesday."],"answer":"You will have sent the document by Tuesday.","explanation":"Future Perfect: Subject + will have + V3. ''ပြီးပြီမယ်'' and ''by Tuesday'' indicate a future completed action. Future Perfect - Subject + will have + V3။","points":2},{"id":370,"question":"သူမ မင်းရောက်ခင် အစည်းအဝေး ဝင်ပြီးမယ်။ (She / joined the meeting / before you reach)","options":["She will have joined the meeting before you reach.","She has joined the meeting before you reach.","She had joined the meeting before you reach."],"answer":"She will have joined the meeting before you reach.","explanation":"Future Perfect: Subject + will have + V3. ''ပြီးမယ်'' and ''before you reach'' indicate a future completed action. Future Perfect - Subject + will have + V3။","points":2},{"id":371,"question":"သူ ဒီလမ်းပေါ်မှာ အရင်က လျှောက်ဖူးတယ်။ (I / walked on this path / before)","options":["I have walked on this path before.","I had walked on this path before.","I will have walked on this path before."],"answer":"I have walked on this path before.","explanation":"Present Perfect: Subject + have + V3. ''ဖူးတယ်'' and ''before'' indicate a past experience relevant to the present. Present Perfect - Subject + have + V3။","points":2},{"id":372,"question":"သူ ရုပ်ရှင်ဇာတ်ညွှန်းတွေ အများကြီး ရေးပြီးပြီ။ (He / written several movie scripts)","options":["He has written several movie scripts.","He have written several movie scripts.","He had written several movie scripts."],"answer":"He has written several movie scripts.","explanation":"Present Perfect: Subject + has + V3. ''ပြီးပြီ'' indicates a completed action. With ''he'', we use ''has''. Present Perfect - Subject + has + V3။","points":2},{"id":373,"question":"ငါ ခရီးသွားဖို့ ထွက်ပြီးပြီမယ်။ (I / left for my trip)","options":["I will have left for my trip.","I have left for my trip.","I had left for my trip."],"answer":"I will have left for my trip.","explanation":"Future Perfect: Subject + will have + V3. ''ပြီးပြီမယ်'' indicates a future completed action. Future Perfect - Subject + will have + V3။","points":2},{"id":374,"question":"သူ ပါတီမတိုင်ခင် သူမကို တွေ့ပြီးပြီလား။ (Had / he / met her / before the party)","options":["Had he met her before the party?","Did he meet her before the party?","Has he met her before the party?"],"answer":"Had he met her before the party?","explanation":"Past Perfect Interrogative: Had + subject + V3? ''လား'' indicates a question. ''Before the party'' indicates past time before another past action. Past Perfect မေးခွန်းပုံ - Had + subject + V3?","points":2},{"id":375,"question":"သူ အရင်က သူ့ကို မြင်ဖူးတယ်။ (I / seen him / before)","options":["I had seen him before.","I have seen him before.","I will have seen him before."],"answer":"I had seen him before.","explanation":"Past Perfect: Subject + had + V3. ''ဖူးတယ်'' and ''before'' indicate an action completed before another past action. Past Perfect - Subject + had + V3။","points":2}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

-- --------------------------------------------------------------------------
-- Unit 4 Exercises
-- --------------------------------------------------------------------------

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00004000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 4), 'unit4-ex1', 'multiple_choice', 'Choose the correct question tag for each statement.', '[{"id":401,"question":"She is from a small town in China, ________?","options":["isn''t she","is she","aren''t she"],"answer":"isn''t she","explanation":"Positive statement with ''is'' → negative tag with ''isn''t''. ''She'' is third person singular. ''She'' ရဲ့ positive statement က ''is'' သုံးထားတဲ့အတွက် negative tag ''isn''t she'' ဖြစ်ရပါမယ်။","points":1},{"id":402,"question":"They aren''t on their way already, ________?","options":["are they","aren''t they","isn''t they"],"answer":"are they","explanation":"Negative statement with ''aren''t'' → positive tag with ''are''. ''They'' requires ''are''. ''They'' ရဲ့ negative statement က ''aren''t'' သုံးထားတဲ့အတွက် positive tag ''are they'' ဖြစ်ရပါမယ်။","points":1},{"id":403,"question":"We are late again, ________?","options":["aren''t we","are we","isn''t we"],"answer":"aren''t we","explanation":"Positive statement with ''are'' → negative tag with ''aren''t''. ''We'' requires ''are''. ''We'' ရဲ့ positive statement က ''are'' သုံးထားတဲ့အတွက် negative tag ''aren''t we'' ဖြစ်ရပါမယ်။","points":1},{"id":404,"question":"I am not the person with the tickets, ________?","options":["am I","aren''t I","isn''t I"],"answer":"am I","explanation":"Negative ''I am not'' → positive tag ''am I''. This is a special case. ''I am not'' ရဲ့ negative statement က positive tag ''am I'' ကို သုံးပါတယ်။ ဒါ special case ပါ။","points":1},{"id":405,"question":"Julie isn''t an accountant, ________?","options":["is she","isn''t she","are she"],"answer":"is she","explanation":"Negative statement with ''isn''t'' → positive tag with ''is''. ''Julie'' is she. ''Julie'' ရဲ့ negative statement က ''isn''t'' သုံးထားတဲ့အတွက် positive tag ''is she'' ဖြစ်ရပါမယ်။","points":1},{"id":406,"question":"I like chocolate very much, ________?","options":["don''t I","do I","doesn''t I"],"answer":"don''t I","explanation":"Positive statement with ''like'' (V1) → negative tag with ''don''t''. ''I'' uses ''don''t''. ''I'' ရဲ့ positive statement က ''like'' (V1) သုံးထားတဲ့အတွက် negative tag ''don''t I'' ဖြစ်ရပါမယ်။","points":1},{"id":407,"question":"She doesn''t work in a hotel, ________?","options":["does she","doesn''t she","do she"],"answer":"does she","explanation":"Negative statement with ''doesn''t'' → positive tag with ''does''. ''She'' uses ''does''. ''She'' ရဲ့ negative statement က ''doesn''t'' သုံးထားတဲ့အတွက် positive tag ''does she'' ဖြစ်ရပါမယ်။","points":1},{"id":408,"question":"They need some new clothes, ________?","options":["don''t they","do they","doesn''t they"],"answer":"don''t they","explanation":"Positive statement with ''need'' (V1) → negative tag with ''don''t''. ''They'' uses ''don''t''. ''They'' ရဲ့ positive statement က ''need'' (V1) သုံးထားတဲ့အတွက် negative tag ''don''t they'' ဖြစ်ရပါမယ်။","points":1},{"id":409,"question":"David and Julie don''t take Chinese classes, ________?","options":["do they","don''t they","does they"],"answer":"do they","explanation":"Negative statement with ''don''t'' → positive tag with ''do''. ''David and Julie'' = they. ''David and Julie'' ရဲ့ negative statement က ''don''t'' သုံးထားတဲ့အတွက် positive tag ''do they'' ဖြစ်ရပါမယ်။","points":1},{"id":410,"question":"John knew about this letter, ________?","options":["didn''t he","doesn''t he","wasn''t he"],"answer":"didn''t he","explanation":"Positive statement with ''knew'' (V2 past) → negative tag with ''didn''t''. Past tense uses ''didn''t''. ''John'' ရဲ့ positive statement က ''knew'' (V2) သုံးထားတဲ့အတွက် negative tag ''didn''t he'' ဖြစ်ရပါမယ်။","points":1},{"id":411,"question":"My parrot can talk, ________?","options":["can''t it","doesn''t it","won''t it"],"answer":"can''t it","explanation":"Positive statement with ''can'' → negative tag with ''can''t''. Modal verb ''can'' uses ''can''t''. ''My parrot'' = it. ''My parrot'' ရဲ့ positive statement က ''can'' သုံးထားတဲ့အတွက် negative tag ''can''t it'' ဖြစ်ရပါမယ်။","points":1},{"id":412,"question":"It never snows in spring, ________?","options":["does it","doesn''t it","isn''t it"],"answer":"does it","explanation":"Negative meaning with ''never'' → positive tag. ''Never'' makes the statement negative. ''It'' မှာ ''never'' ပါတဲ့အတွက် statement က negative ဖြစ်ပြီး positive tag ''does it'' ဖြစ်ရပါမယ်။","points":1},{"id":413,"question":"Our bus has arrived, ________?","options":["hasn''t it","haven''t it","doesn''t it"],"answer":"hasn''t it","explanation":"Positive statement with ''has arrived'' (present perfect) → negative tag with ''hasn''t''. ''Our bus'' = it. ''Our bus'' ရဲ့ positive statement က ''has arrived'' (present perfect) သုံးထားတဲ့အတွက် negative tag ''hasn''t it'' ဖြစ်ရပါမယ်။","points":1},{"id":414,"question":"There are some bees, ________?","options":["aren''t there","are there","isn''t there"],"answer":"aren''t there","explanation":"Positive statement with ''are'' → negative tag with ''aren''t''. ''There'' sentences use ''there'' in the tag. ''There'' sentence မှာ positive statement ''are'' သုံးထားတဲ့အတွက် negative tag ''aren''t there'' ဖြစ်ရပါမယ်။","points":1},{"id":415,"question":"Jack is from Spain, ________?","options":["isn''t he","is he","aren''t he"],"answer":"isn''t he","explanation":"Positive statement with ''is'' → negative tag with ''isn''t''. ''Jack'' = he. ''Jack'' ရဲ့ positive statement က ''is'' သုံးထားတဲ့အတွက် negative tag ''isn''t he'' ဖြစ်ရပါမယ်။","points":1},{"id":416,"question":"You are a teacher, ________?","options":["aren''t you","are you","isn''t you"],"answer":"aren''t you","explanation":"Positive statement with ''are'' → negative tag with ''aren''t''. ''You'' requires ''are''. ''You'' ရဲ့ positive statement က ''are'' သုံးထားတဲ့အတွက် negative tag ''aren''t you'' ဖြစ်ရပါမယ်။","points":1},{"id":417,"question":"The film was fantastic, ________?","options":["wasn''t it","was it","weren''t it"],"answer":"wasn''t it","explanation":"Positive statement with ''was'' → negative tag with ''wasn''t''. ''The film'' = it. ''The film'' ရဲ့ positive statement က ''was'' သုံးထားတဲ့အတွက် negative tag ''wasn''t it'' ဖြစ်ရပါမယ်။","points":1},{"id":418,"question":"They were surprised, ________?","options":["weren''t they","wasn''t they","aren''t they"],"answer":"weren''t they","explanation":"Positive statement with ''were'' → negative tag with ''weren''t''. ''They'' requires ''were''. ''They'' ရဲ့ positive statement က ''were'' သုံးထားတဲ့အတွက် negative tag ''weren''t they'' ဖြစ်ရပါမယ်။","points":1},{"id":419,"question":"You had arrived before he left, ________?","options":["hadn''t you","didn''t you","weren''t you"],"answer":"hadn''t you","explanation":"Positive statement with ''had arrived'' (past perfect) → negative tag with ''hadn''t''. Past perfect uses ''had''. ''You'' ရဲ့ positive statement က ''had arrived'' (past perfect) သုံးထားတဲ့အတွက် negative tag ''hadn''t you'' ဖြစ်ရပါမယ်။","points":1},{"id":420,"question":"We must be patient, ________?","options":["mustn''t we","don''t we","aren''t we"],"answer":"mustn''t we","explanation":"Positive statement with ''must'' → negative tag with ''mustn''t''. Modal verb ''must'' uses ''mustn''t''. ''We'' ရဲ့ positive statement က ''must'' သုံးထားတဲ့အတွက် negative tag ''mustn''t we'' ဖြစ်ရပါမယ်။","points":1},{"id":421,"question":"You should go now, ________?","options":["shouldn''t you","don''t you","won''t you"],"answer":"shouldn''t you","explanation":"Positive statement with ''should'' → negative tag with ''shouldn''t''. Modal verb ''should'' uses ''shouldn''t''. ''You'' ရဲ့ positive statement က ''should'' သုံးထားတဲ့အတွက် negative tag ''shouldn''t you'' ဖြစ်ရပါမယ်။","points":1},{"id":422,"question":"You would like a new job, ________?","options":["wouldn''t you","don''t you","won''t you"],"answer":"wouldn''t you","explanation":"Positive statement with ''would'' → negative tag with ''wouldn''t''. Modal verb ''would'' uses ''wouldn''t''. ''You'' ရဲ့ positive statement က ''would'' သုံးထားတဲ့အတွက် negative tag ''wouldn''t you'' ဖြစ်ရပါမယ်။","points":1},{"id":423,"question":"He isn''t crazy, ________?","options":["is he","isn''t he","aren''t he"],"answer":"is he","explanation":"Negative statement with ''isn''t'' → positive tag with ''is''. ''He'' uses ''is''. ''He'' ရဲ့ negative statement က ''isn''t'' သုံးထားတဲ့အတွက် positive tag ''is he'' ဖြစ်ရပါမယ်။","points":1},{"id":424,"question":"He wasn''t sick, ________?","options":["was he","weren''t he","is he"],"answer":"was he","explanation":"Negative statement with ''wasn''t'' → positive tag with ''was''. ''He'' uses ''was''. ''He'' ရဲ့ negative statement က ''wasn''t'' သုံးထားတဲ့အတွက် positive tag ''was he'' ဖြစ်ရပါမယ်။","points":1},{"id":425,"question":"We weren''t late, ________?","options":["were we","weren''t we","was we"],"answer":"were we","explanation":"Negative statement with ''weren''t'' → positive tag with ''were''. ''We'' uses ''were''. ''We'' ရဲ့ negative statement က ''weren''t'' သုံးထားတဲ့အတွက် positive tag ''were we'' ဖြစ်ရပါမယ်။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00004001-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 4), 'unit4-ex2', 'multiple_choice', 'Choose the correct statement that matches the given question tag.', '[{"id":426,"question":"isn''t she? → Which statement matches this tag?","options":["She is from a small town in China,","She isn''t from a small town in China,","She was from a small town in China,"],"answer":"She is from a small town in China,","explanation":"''isn''t she?'' is a negative tag, so the statement must be positive with ''is''. ''isn''t she?'' က negative tag ဖြစ်တဲ့အတွက် statement က positive ''is'' ဖြစ်ရပါမယ်။","points":1},{"id":427,"question":"are they? → Which statement matches this tag?","options":["They aren''t on their way already,","They are on their way already,","They weren''t on their way already,"],"answer":"They aren''t on their way already,","explanation":"''are they?'' is a positive tag, so the statement must be negative with ''aren''t''. ''are they?'' က positive tag ဖြစ်တဲ့အတွက် statement က negative ''aren''t'' ဖြစ်ရပါမယ်။","points":1},{"id":428,"question":"aren''t we? → Which statement matches this tag?","options":["We are late again,","We aren''t late again,","We were late again,"],"answer":"We are late again,","explanation":"''aren''t we?'' is a negative tag, so the statement must be positive with ''are''. ''aren''t we?'' က negative tag ဖြစ်တဲ့အတွက် statement က positive ''are'' ဖြစ်ရပါမယ်။","points":1},{"id":429,"question":"don''t I? → Which statement matches this tag?","options":["I like chocolate very much,","I don''t like chocolate very much,","I liked chocolate very much,"],"answer":"I like chocolate very much,","explanation":"''don''t I?'' is a negative tag, so the statement must be positive with V1. ''don''t I?'' က negative tag ဖြစ်တဲ့အတွက် statement က positive V1 ဖြစ်ရပါမယ်။","points":1},{"id":430,"question":"does she? → Which statement matches this tag?","options":["She doesn''t work in a hotel,","She works in a hotel,","She worked in a hotel,"],"answer":"She doesn''t work in a hotel,","explanation":"''does she?'' is a positive tag, so the statement must be negative with ''doesn''t''. ''does she?'' က positive tag ဖြစ်တဲ့အတွက် statement က negative ''doesn''t'' ဖြစ်ရပါမယ်။","points":1},{"id":431,"question":"don''t they? → Which statement matches this tag?","options":["They need some new clothes,","They don''t need some new clothes,","They needed some new clothes,"],"answer":"They need some new clothes,","explanation":"''don''t they?'' is a negative tag, so the statement must be positive with V1. ''don''t they?'' က negative tag ဖြစ်တဲ့အတွက် statement က positive V1 ဖြစ်ရပါမယ်။","points":1},{"id":432,"question":"do they? → Which statement matches this tag?","options":["David and Julie don''t take Chinese classes,","David and Julie take Chinese classes,","David and Julie didn''t take Chinese classes,"],"answer":"David and Julie don''t take Chinese classes,","explanation":"''do they?'' is a positive tag, so the statement must be negative with ''don''t''. ''do they?'' က positive tag ဖြစ်တဲ့အတွက် statement က negative ''don''t'' ဖြစ်ရပါမယ်။","points":1},{"id":433,"question":"didn''t he? → Which statement matches this tag?","options":["John knew about this letter,","John doesn''t know about this letter,","John knows about this letter,"],"answer":"John knew about this letter,","explanation":"''didn''t he?'' is a negative tag, so the statement must be positive with V2 (past). ''didn''t he?'' က negative tag ဖြစ်တဲ့အတွက် statement က positive V2 (past) ဖြစ်ရပါမယ်။","points":1},{"id":434,"question":"can''t it? → Which statement matches this tag?","options":["My parrot can talk,","My parrot can''t talk,","My parrot could talk,"],"answer":"My parrot can talk,","explanation":"''can''t it?'' is a negative tag, so the statement must be positive with ''can''. ''can''t it?'' က negative tag ဖြစ်တဲ့အတွက် statement က positive ''can'' ဖြစ်ရပါမယ်။","points":1},{"id":435,"question":"does it? → Which statement matches this tag?","options":["It never snows in spring,","It always snows in spring,","It doesn''t snow in spring,"],"answer":"It never snows in spring,","explanation":"''does it?'' is a positive tag, so the statement must have negative meaning. ''never'' makes the statement negative. ''does it?'' က positive tag ဖြစ်တဲ့အတွက် statement က negative meaning ''never'' ပါရပါမယ်။","points":1},{"id":436,"question":"hasn''t it? → Which statement matches this tag?","options":["Our bus has arrived,","Our bus hasn''t arrived,","Our bus had arrived,"],"answer":"Our bus has arrived,","explanation":"''hasn''t it?'' is a negative tag, so the statement must be positive with ''has''. ''hasn''t it?'' က negative tag ဖြစ်တဲ့အတွက် statement က positive ''has'' ဖြစ်ရပါမယ်။","points":1},{"id":437,"question":"aren''t there? → Which statement matches this tag?","options":["There are some bees,","There aren''t some bees,","There were some bees,"],"answer":"There are some bees,","explanation":"''aren''t there?'' is a negative tag, so the statement must be positive with ''are''. ''aren''t there?'' က negative tag ဖြစ်တဲ့အတွက် statement က positive ''are'' ဖြစ်ရပါမယ်။","points":1},{"id":438,"question":"aren''t you? → Which statement matches this tag?","options":["You are a teacher,","You aren''t a teacher,","You were a teacher,"],"answer":"You are a teacher,","explanation":"''aren''t you?'' is a negative tag, so the statement must be positive with ''are''. ''aren''t you?'' က negative tag ဖြစ်တဲ့အတွက် statement က positive ''are'' ဖြစ်ရပါမယ်။","points":1},{"id":439,"question":"wasn''t it? → Which statement matches this tag?","options":["The film was fantastic,","The film wasn''t fantastic,","The film were fantastic,"],"answer":"The film was fantastic,","explanation":"''wasn''t it?'' is a negative tag, so the statement must be positive with ''was''. ''wasn''t it?'' က negative tag ဖြစ်တဲ့အတွက် statement က positive ''was'' ဖြစ်ရပါမယ်။","points":1},{"id":440,"question":"weren''t they? → Which statement matches this tag?","options":["They were surprised,","They weren''t surprised,","They are surprised,"],"answer":"They were surprised,","explanation":"''weren''t they?'' is a negative tag, so the statement must be positive with ''were''. ''weren''t they?'' က negative tag ဖြစ်တဲ့အတွက် statement က positive ''were'' ဖြစ်ရပါမယ်။","points":1},{"id":441,"question":"hadn''t you? → Which statement matches this tag?","options":["You had arrived before he left,","You hadn''t arrived before he left,","You arrived before he left,"],"answer":"You had arrived before he left,","explanation":"''hadn''t you?'' is a negative tag, so the statement must be positive with ''had''. ''hadn''t you?'' က negative tag ဖြစ်တဲ့အတွက် statement က positive ''had'' ဖြစ်ရပါမယ်။","points":1},{"id":442,"question":"mustn''t we? → Which statement matches this tag?","options":["We must be patient,","We mustn''t be patient,","We should be patient,"],"answer":"We must be patient,","explanation":"''mustn''t we?'' is a negative tag, so the statement must be positive with ''must''. ''mustn''t we?'' က negative tag ဖြစ်တဲ့အတွက် statement က positive ''must'' ဖြစ်ရပါမယ်။","points":1},{"id":443,"question":"shouldn''t you? → Which statement matches this tag?","options":["You should go now,","You shouldn''t go now,","You will go now,"],"answer":"You should go now,","explanation":"''shouldn''t you?'' is a negative tag, so the statement must be positive with ''should''. ''shouldn''t you?'' က negative tag ဖြစ်တဲ့အတွက် statement က positive ''should'' ဖြစ်ရပါမယ်။","points":1},{"id":444,"question":"wouldn''t you? → Which statement matches this tag?","options":["You would like a new job,","You wouldn''t like a new job,","You will like a new job,"],"answer":"You would like a new job,","explanation":"''wouldn''t you?'' is a negative tag, so the statement must be positive with ''would''. ''wouldn''t you?'' က negative tag ဖြစ်တဲ့အတွက် statement က positive ''would'' ဖြစ်ရပါမယ်။","points":1},{"id":445,"question":"is he? → Which statement matches this tag?","options":["He isn''t crazy,","He is crazy,","He wasn''t crazy,"],"answer":"He isn''t crazy,","explanation":"''is he?'' is a positive tag, so the statement must be negative with ''isn''t''. ''is he?'' က positive tag ဖြစ်တဲ့အတွက် statement က negative ''isn''t'' ဖြစ်ရပါမယ်။","points":1},{"id":446,"question":"was he? → Which statement matches this tag?","options":["He wasn''t sick,","He was sick,","He isn''t sick,"],"answer":"He wasn''t sick,","explanation":"''was he?'' is a positive tag, so the statement must be negative with ''wasn''t''. ''was he?'' က positive tag ဖြစ်တဲ့အတွက် statement က negative ''wasn''t'' ဖြစ်ရပါမယ်။","points":1},{"id":447,"question":"were we? → Which statement matches this tag?","options":["We weren''t late,","We were late,","We aren''t late,"],"answer":"We weren''t late,","explanation":"''were we?'' is a positive tag, so the statement must be negative with ''weren''t''. ''were we?'' က positive tag ဖြစ်တဲ့အတွက် statement က negative ''weren''t'' ဖြစ်ရပါမယ်။","points":1},{"id":448,"question":"will you? → Which statement matches this tag?","options":["Close the window,","You close the window,","You will close the window,"],"answer":"Close the window,","explanation":"''will you?'' is used after imperative statements. ''Close the window'' is an imperative. ''will you?'' က imperative statement ပြီးနောက်မှာ သုံးပါတယ်။ ''Close the window'' က imperative ဖြစ်ပါတယ်။","points":1},{"id":449,"question":"shall we? → Which statement matches this tag?","options":["Let''s go to the beach,","We will go to the beach,","We go to the beach,"],"answer":"Let''s go to the beach,","explanation":"''shall we?'' is used after ''Let''s'' statements. ''Let''s go to the beach'' is the matching statement. ''shall we?'' က ''Let''s'' statement ပြီးနောက်မှာ သုံးပါတယ်။","points":1},{"id":450,"question":"do they? → Which statement matches this tag?","options":["Nobody lives in this house,","Somebody lives in this house,","Everybody lives in this house,"],"answer":"Nobody lives in this house,","explanation":"''do they?'' is a positive tag, used with negative pronouns like ''nobody''. ''do they?'' က positive tag ဖြစ်ပြီး ''nobody'' လို negative pronoun နဲ့ သုံးပါတယ်။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00004002-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 4), 'unit4-ex3', 'multiple_choice', 'Complete the sentence with the correct question tag. Pay attention to special cases and exceptions.', '[{"id":451,"question":"You play the guitar, ________?","options":["don''t you","doesn''t you","aren''t you"],"answer":"don''t you","explanation":"Positive statement with ''play'' (V1) → negative tag ''don''t you''. Simple present positive uses ''don''t''. ''You'' ရဲ့ positive statement က ''play'' (V1) သုံးထားတဲ့အတွက် negative tag ''don''t you'' ဖြစ်ရပါမယ်။","points":2},{"id":452,"question":"Sue likes tennis, ________?","options":["doesn''t she","don''t she","isn''t she"],"answer":"doesn''t she","explanation":"Positive statement with ''likes'' (V1+s) → negative tag ''doesn''t she''. He/she/it uses ''doesn''t''. ''Sue'' က he/she/it ဖြစ်တဲ့အတွက် ''likes'' (V1+s) positive statement → ''doesn''t she'' negative tag ဖြစ်ရပါမယ်။","points":2},{"id":453,"question":"You went there, ________?","options":["didn''t you","don''t you","weren''t you"],"answer":"didn''t you","explanation":"Positive statement with ''went'' (V2 past) → negative tag ''didn''t you''. Past tense uses ''didn''t''. ''You'' ရဲ့ positive statement က ''went'' (V2) သုံးထားတဲ့အတွက် negative tag ''didn''t you'' ဖြစ်ရပါမယ်။","points":2},{"id":454,"question":"You will pass the exam, ________?","options":["won''t you","don''t you","aren''t you"],"answer":"won''t you","explanation":"Positive statement with ''will'' → negative tag ''won''t you''. Future tense uses ''won''t''. ''You'' ရဲ့ positive statement က ''will'' သုံးထားတဲ့အတွက် negative tag ''won''t you'' ဖြစ်ရပါမယ်။","points":2},{"id":455,"question":"You have studied all week, ________?","options":["haven''t you","don''t you","hasn''t you"],"answer":"haven''t you","explanation":"Positive statement with ''have studied'' (present perfect) → negative tag ''haven''t you''. ''You'' uses ''haven''t''. ''You'' ရဲ့ positive statement က ''have studied'' (present perfect) သုံးထားတဲ့အတွက် negative tag ''haven''t you'' ဖြစ်ရပါမယ်။","points":2},{"id":456,"question":"She has written a letter for 2 days, ________?","options":["hasn''t she","haven''t she","doesn''t she"],"answer":"hasn''t she","explanation":"Positive statement with ''has written'' (present perfect) → negative tag ''hasn''t she''. ''She'' uses ''hasn''t''. ''She'' ရဲ့ positive statement က ''has written'' (present perfect) သုံးထားတဲ့အတွက် negative tag ''hasn''t she'' ဖြစ်ရပါမယ်။","points":2},{"id":457,"question":"You had arrived before he left, ________?","options":["hadn''t you","didn''t you","weren''t you"],"answer":"hadn''t you","explanation":"Positive statement with ''had arrived'' (past perfect) → negative tag ''hadn''t you''. Past perfect uses ''hadn''t''. ''You'' ရဲ့ positive statement က ''had arrived'' (past perfect) သုံးထားတဲ့အတွက် negative tag ''hadn''t you'' ဖြစ်ရပါမယ်။","points":2},{"id":458,"question":"Mary can speak English, ________?","options":["can''t she","doesn''t she","won''t she"],"answer":"can''t she","explanation":"Positive statement with ''can'' → negative tag ''can''t she''. Modal verb ''can'' uses ''can''t''. ''Mary'' ရဲ့ positive statement က ''can'' သုံးထားတဲ့အတွက် negative tag ''can''t she'' ဖြစ်ရပါမယ်။","points":2},{"id":459,"question":"We must be patient, ________?","options":["mustn''t we","don''t we","aren''t we"],"answer":"mustn''t we","explanation":"Positive statement with ''must'' → negative tag ''mustn''t we''. Modal verb ''must'' uses ''mustn''t''. ''We'' ရဲ့ positive statement က ''must'' သုံးထားတဲ့အတွက် negative tag ''mustn''t we'' ဖြစ်ရပါမယ်။","points":2},{"id":460,"question":"You should go now, ________?","options":["shouldn''t you","don''t you","won''t you"],"answer":"shouldn''t you","explanation":"Positive statement with ''should'' → negative tag ''shouldn''t you''. Modal verb ''should'' uses ''shouldn''t''. ''You'' ရဲ့ positive statement က ''should'' သုံးထားတဲ့အတွက် negative tag ''shouldn''t you'' ဖြစ်ရပါမယ်။","points":2},{"id":461,"question":"You would like a new job, ________?","options":["wouldn''t you","don''t you","won''t you"],"answer":"wouldn''t you","explanation":"Positive statement with ''would'' → negative tag ''wouldn''t you''. Modal verb ''would'' uses ''wouldn''t''. ''You'' ရဲ့ positive statement က ''would'' သုံးထားတဲ့အတွက် negative tag ''wouldn''t you'' ဖြစ်ရပါမယ်။","points":2},{"id":462,"question":"You don''t go there, ________?","options":["do you","don''t you","aren''t you"],"answer":"do you","explanation":"Negative statement with ''don''t'' → positive tag ''do you''. Negative statement → positive tag. ''You'' ရဲ့ negative statement က ''don''t'' သုံးထားတဲ့အတွက် positive tag ''do you'' ဖြစ်ရပါမယ်။","points":2},{"id":463,"question":"She doesn''t iron the clothes, ________?","options":["does she","doesn''t she","do she"],"answer":"does she","explanation":"Negative statement with ''doesn''t'' → positive tag ''does she''. Negative statement → positive tag. ''She'' ရဲ့ negative statement က ''doesn''t'' သုံးထားတဲ့အတွက် positive tag ''does she'' ဖြစ်ရပါမယ်။","points":2},{"id":464,"question":"You didn''t do your homework, ________?","options":["did you","don''t you","wasn''t you"],"answer":"did you","explanation":"Negative statement with ''didn''t'' → positive tag ''did you''. Negative past statement → positive tag. ''You'' ရဲ့ negative statement က ''didn''t'' သုံးထားတဲ့အတွက် positive tag ''did you'' ဖြစ်ရပါမယ်။","points":2},{"id":465,"question":"You won''t fail the exam, ________?","options":["will you","won''t you","don''t you"],"answer":"will you","explanation":"Negative statement with ''won''t'' → positive tag ''will you''. Negative future statement → positive tag. ''You'' ရဲ့ negative statement က ''won''t'' သုံးထားတဲ့အတွက် positive tag ''will you'' ဖြစ်ရပါမယ်။","points":2},{"id":466,"question":"He isn''t crazy, ________?","options":["is he","isn''t he","aren''t he"],"answer":"is he","explanation":"Negative statement with ''isn''t'' → positive tag ''is he''. Negative be statement → positive tag. ''He'' ရဲ့ negative statement က ''isn''t'' သုံးထားတဲ့အတွက် positive tag ''is he'' ဖြစ်ရပါမယ်။","points":2},{"id":467,"question":"They aren''t funny, ________?","options":["are they","aren''t they","isn''t they"],"answer":"are they","explanation":"Negative statement with ''aren''t'' → positive tag ''are they''. Negative be statement → positive tag. ''They'' ရဲ့ negative statement က ''aren''t'' သုံးထားတဲ့အတွက် positive tag ''are they'' ဖြစ်ရပါမယ်။","points":2},{"id":468,"question":"He wasn''t sick, ________?","options":["was he","weren''t he","is he"],"answer":"was he","explanation":"Negative statement with ''wasn''t'' → positive tag ''was he''. Negative past be statement → positive tag. ''He'' ရဲ့ negative statement က ''wasn''t'' သုံးထားတဲ့အတွက် positive tag ''was he'' ဖြစ်ရပါမယ်။","points":2},{"id":469,"question":"We weren''t late, ________?","options":["were we","weren''t we","was we"],"answer":"were we","explanation":"Negative statement with ''weren''t'' → positive tag ''were we''. Negative past be statement → positive tag. ''We'' ရဲ့ negative statement က ''weren''t'' သုံးထားတဲ့အတွက် positive tag ''were we'' ဖြစ်ရပါမယ်။","points":2},{"id":470,"question":"You haven''t been here all week, ________?","options":["have you","haven''t you","has you"],"answer":"have you","explanation":"Negative statement with ''haven''t'' → positive tag ''have you''. Negative present perfect statement → positive tag. ''You'' ရဲ့ negative statement က ''haven''t'' သုံးထားတဲ့အတွက် positive tag ''have you'' ဖြစ်ရပါမယ်။","points":2},{"id":471,"question":"She hasn''t written a letter, ________?","options":["has she","haven''t she","doesn''t she"],"answer":"has she","explanation":"Negative statement with ''hasn''t'' → positive tag ''has she''. Negative present perfect statement → positive tag. ''She'' ရဲ့ negative statement က ''hasn''t'' သုံးထားတဲ့အတွက် positive tag ''has she'' ဖြစ်ရပါမယ်။","points":2},{"id":472,"question":"John can''t drive a car, ________?","options":["can he","can''t he","doesn''t he"],"answer":"can he","explanation":"Negative statement with ''can''t'' → positive tag ''can he''. Negative modal statement → positive tag. ''John'' ရဲ့ negative statement က ''can''t'' သုံးထားတဲ့အတွက် positive tag ''can he'' ဖြစ်ရပါမယ်။","points":2},{"id":473,"question":"He shouldn''t say things like that, ________?","options":["should he","shouldn''t he","doesn''t he"],"answer":"should he","explanation":"Negative statement with ''shouldn''t'' → positive tag ''should he''. Negative modal statement → positive tag. ''He'' ရဲ့ negative statement က ''shouldn''t'' သုံးထားတဲ့အတွက် positive tag ''should he'' ဖြစ်ရပါမယ်။","points":2},{"id":474,"question":"They wouldn''t stop me, ________?","options":["would they","wouldn''t they","didn''t they"],"answer":"would they","explanation":"Negative statement with ''wouldn''t'' → positive tag ''would they''. Negative modal statement → positive tag. ''They'' ရဲ့ negative statement က ''wouldn''t'' သုံးထားတဲ့အတွက် positive tag ''would they'' ဖြစ်ရပါမယ်။","points":2},{"id":475,"question":"We mustn''t say anything, ________?","options":["must we","mustn''t we","don''t we"],"answer":"must we","explanation":"Negative statement with ''mustn''t'' → positive tag ''must we''. Negative modal statement → positive tag. ''We'' ရဲ့ negative statement က ''mustn''t'' သုံးထားတဲ့အတွက် positive tag ''must we'' ဖြစ်ရပါမယ်။","points":2}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

-- --------------------------------------------------------------------------
-- Unit 5 Exercises
